import type { MenuSteps } from "./menuStepsTypes";

export const ADMIN_STEPS: MenuSteps = {
  system: [
    { target: "sys-machine", placement: "bottom",
      t: ["The live machine", "La máquina en directo", "Die Maschine live", "La machine en direct", "La macchina dal vivo", "マシンのライブ状態", "机器实时状态", "A máquina em direto"],
      b: ["The first card shows the machine that runs the server: processor, memory, temperature, disk and network, with small live charts and the heaviest programs. A bar turns warm and then hot as it fills. Look here first when Studio feels slow: a processor at the limit, a full disk or a high temperature explains most problems before you look anywhere else.",
        "La primera tarjeta muestra la máquina que ejecuta el servidor: procesador, memoria, temperatura, disco y red, con pequeñas gráficas en vivo y los programas que más consumen. Una barra se pone cálida y luego caliente al llenarse. Mira aquí primero cuando Studio vaya lento: un procesador al límite, un disco lleno o una temperatura alta explican la mayoría de los problemas antes de buscar en otro sitio.",
        "Die erste Karte zeigt die Maschine, auf der der Server läuft: Prozessor, Speicher, Temperatur, Datenträger und Netz, mit kleinen Live-Diagrammen und den aufwendigsten Programmen. Ein Balken wird warm und dann heiß, wenn er sich füllt. Schauen Sie zuerst hier nach, wenn Studio träge wirkt: Ein ausgelasteter Prozessor, eine volle Platte oder hohe Temperatur erklären die meisten Probleme.",
        "La première carte montre la machine qui exécute le serveur : processeur, mémoire, température, disque et réseau, avec de petits graphiques en direct et les programmes les plus gourmands. Une barre devient chaude puis brûlante en se remplissant. Regardez ici d'abord quand Studio semble lent : un processeur saturé, un disque plein ou une température élevée expliquent la plupart des problèmes.",
        "La prima scheda mostra la macchina che esegue il server: processore, memoria, temperatura, disco e rete, con piccoli grafici dal vivo e i programmi più pesanti. Una barra diventa calda e poi rovente riempiendosi. Guarda qui per primo quando Studio sembra lento: un processore al limite, un disco pieno o una temperatura alta spiegano la maggior parte dei problemi.",
        "最初のカードはサーバーを動かすマシンの状態です：CPU、メモリ、温度、ディスク、ネットワークを小さなライブグラフで表示し、負荷の大きいプログラムも出ます。バーは埋まるにつれて警戒色になります。Studioが重いと感じたら、まずここを見ましょう。CPUの飽和、ディスクの満杯、高温が大半の原因です。",
        "第一张卡片显示运行服务器的机器：处理器、内存、温度、磁盘和网络，带有小型实时图表和最耗资源的程序。进度条随占用升高变暖色再变热色。Studio 变慢时先看这里：处理器跑满、磁盘已满或温度过高能解释大多数问题。",
        "O primeiro cartão mostra a máquina que executa o servidor: processador, memória, temperatura, disco e rede, com pequenos gráficos em direto e os programas que mais consomem. Uma barra fica quente e depois muito quente ao encher. Olhe aqui primeiro quando o Studio parecer lento: um processador no limite, um disco cheio ou uma temperatura alta explicam a maioria dos problemas."] },
    { target: "sys-grid", placement: "bottom",
      t: ["What the server holds and its links", "Lo que guarda el servidor y sus conexiones", "Was der Server hält und seine Verbindungen", "Ce que le serveur contient et ses liens", "Cosa contiene il server e i suoi collegamenti", "サーバーの保有内容と接続", "服务器的保有内容与连接", "O que o servidor guarda e as suas ligações"],
      b: ["Above, the version, the uptime, the mode and the revision. The cards show what the server holds (nodes, cameras, devices, alarms, automations, users, events), its storage (the media against its limit, and the disk used and free) and its links: the MQTT broker, the live video program (FFmpeg) that turns camera streams into pictures, and the alarm webhook, each saying whether it answers. A red card means the thing it describes has a problem: follow it in Services or in the logs.",
        "Arriba, la versión, el tiempo en marcha, el modo y la revisión. Las tarjetas muestran lo que guarda el servidor (nodos, cámaras, dispositivos, alarmas, automatizaciones, usuarios, eventos), su almacenamiento (los medios frente a su límite, y el disco usado y libre) y sus conexiones: el broker MQTT, el programa de vídeo en vivo (FFmpeg) que convierte los flujos de cámara en imágenes y el webhook de alarma, cada una diciendo si responde. Una tarjeta roja significa que lo que describe tiene un problema: síguelo en Servicios o en los registros.",
        "Oben Version, Laufzeit, Modus und Revision. Die Karten zeigen, was der Server hält (Knoten, Kameras, Geräte, Alarme, Automationen, Benutzer, Ereignisse), seinen Speicher (Medien gegen das Limit sowie Datenträger belegt und frei) und seine Verbindungen: den MQTT-Broker, das Live-Video-Programm (FFmpeg), das Kamerastreams in Bilder verwandelt, und den Alarm-Webhook, jeweils mit Angabe, ob er antwortet. Eine rote Karte heißt: Das Beschriebene hat ein Problem - verfolgen Sie es unter Dienste oder in den Protokollen.",
        "En haut, la version, la durée de fonctionnement, le mode et la révision. Les cartes montrent ce que le serveur contient (nœuds, caméras, appareils, alarmes, automatisations, utilisateurs, événements), son stockage (les médias face à leur limite, et le disque utilisé et libre) et ses liens : le broker MQTT, le programme vidéo en direct (FFmpeg) qui transforme les flux de caméra en images, et le webhook d'alarme, chacun disant s'il répond. Une carte rouge signifie que ce qu'elle décrit a un problème : suivez-le dans Services ou dans les journaux.",
        "In alto, versione, tempo di attività, modalità e revisione. Le schede mostrano cosa contiene il server (nodi, telecamere, dispositivi, allarmi, automazioni, utenti, eventi), il suo archivio (i media rispetto al limite, e il disco usato e libero) e i suoi collegamenti: il broker MQTT, il programma video dal vivo (FFmpeg) che trasforma i flussi delle telecamere in immagini, e il webhook di allarme, ciascuno dicendo se risponde. Una scheda rossa significa che ciò che descrive ha un problema: seguilo in Servizi o nei registri.",
        "上部にバージョン、稼働時間、モード、リビジョンがあります。カードはサーバーが保持するもの（ノード、カメラ、デバイス、アラーム、オートメーション、ユーザー、イベント）、ストレージ（メディアの上限に対する量、ディスクの使用量と空き）、接続（MQTTブローカー、カメラのストリームを映像に変えるライブ映像プログラムFFmpeg、アラームWebhook。それぞれ応答の有無）を示します。赤いカードは問題があるということ。サービスやログで原因を追ってください。",
        "上方是版本、运行时间、模式和修订号。卡片显示服务器保存的内容（节点、摄像头、设备、报警、自动化、用户、事件）、存储（媒体占用与上限，以及磁盘已用和空闲）和连接：MQTT 代理、把摄像头视频流转为图像的实时视频程序（FFmpeg）和报警 webhook，每项都会说明是否有响应。卡片变红表示它描述的对象有问题：到“服务”或日志中追查。",
        "Em cima, a versão, o tempo de funcionamento, o modo e a revisão. Os cartões mostram o que o servidor guarda (nós, câmaras, dispositivos, alarmes, automatizações, utilizadores, eventos), o seu armazenamento (os media face ao limite, e o disco usado e livre) e as suas ligações: o broker MQTT, o programa de vídeo em direto (FFmpeg) que transforma os fluxos das câmaras em imagens, e o webhook de alarme, cada um a dizer se responde. Um cartão vermelho significa que o que descreve tem um problema: siga-o em Serviços ou nos registos."] },
    { target: "sys-health", placement: "top",
      t: ["Health of the nodes", "Salud de los nodos", "Zustand der Knoten", "Santé des nœuds", "Salute dei nodi", "ノードの状態", "节点健康状况", "Saúde dos nós"],
      b: ["One card for every radar, solar, electrical, alarm and wall-panel node, all with the same report: how long it has been up, why it last restarted (a crash or a watchdog is marked as unexpected), its free memory, its link (Wi-Fi with the signal, or the cable), how many times it connected to the broker and the last error it logged. The server raises a warning in Alarms when a node is short of memory, restarts too often, keeps losing the broker or has a weak Wi-Fi signal. Press Details for the history of its memory and signal and its restarts. A node listed as waiting has sent no report yet: it runs an older firmware, or the broker does not let it write.",
        "Una tarjeta por cada nodo de radar, solar, eléctrico, de alarma y de panel de pared, todas con el mismo informe: cuánto lleva encendido, por qué se reinició la última vez (un fallo o un perro guardián se marca como inesperado), su memoria libre, su enlace (Wi-Fi con la señal, o el cable), cuántas veces se conectó al broker y el último error que anotó. El servidor levanta un aviso en Alarmas cuando un nodo anda corto de memoria, se reinicia demasiado, pierde el broker una y otra vez o tiene poca señal Wi-Fi. Pulsa Detalles para ver el historial de su memoria y su señal y sus reinicios. Un nodo en espera aún no ha enviado informe: tiene un firmware antiguo o el broker no le deja escribirlo.",
        "Eine Karte für jeden Radar-, Solar-, Elektro-, Alarm- und Wandpanel-Knoten, alle mit demselben Bericht: wie lange er läuft, warum er zuletzt neu gestartet ist (ein Absturz oder ein Watchdog gilt als unerwartet), der freie Speicher, die Verbindung (WLAN mit Signal oder Kabel), wie oft er sich mit dem Broker verbunden hat und der letzte protokollierte Fehler. Der Server löst in den Alarmen eine Warnung aus, wenn einem Knoten der Speicher knapp wird, er zu oft neu startet, den Broker immer wieder verliert oder ein schwaches WLAN-Signal hat. Mit Details sehen Sie den Verlauf von Speicher und Signal und die Neustarts. Ein wartender Knoten hat noch keinen Bericht gesendet: Er hat eine ältere Firmware, oder der Broker lässt ihn nicht schreiben.",
        "Une carte pour chaque nœud radar, solaire, électrique, d'alarme et de panneau mural, toutes avec le même rapport : depuis combien de temps il tourne, pourquoi il a redémarré la dernière fois (un plantage ou un chien de garde est marqué inattendu), sa mémoire libre, sa liaison (Wi-Fi avec le signal, ou le câble), combien de fois il s'est connecté au broker et la dernière erreur notée. Le serveur lève un avertissement dans Alarmes quand un nœud manque de mémoire, redémarre trop souvent, perd le broker à répétition ou a un signal Wi-Fi faible. Appuyez sur Détails pour l'historique de sa mémoire et de son signal et ses redémarrages. Un nœud en attente n'a pas encore envoyé de rapport : micrologiciel ancien, ou le broker ne le laisse pas écrire.",
        "Una scheda per ogni nodo radar, solare, elettrico, di allarme e a pannello da parete, tutte con lo stesso rapporto: da quanto è acceso, perché si è riavviato l'ultima volta (un arresto anomalo o un watchdog è segnato come inatteso), la memoria libera, il collegamento (Wi-Fi con il segnale, o il cavo), quante volte si è connesso al broker e l'ultimo errore registrato. Il server solleva un avviso in Allarmi quando a un nodo manca la memoria, si riavvia troppo spesso, perde di continuo il broker o ha un segnale Wi-Fi debole. Premi Dettagli per la cronologia di memoria e segnale e i riavvii. Un nodo in attesa non ha ancora inviato un rapporto: ha un firmware vecchio, o il broker non gli lascia scrivere.",
        "レーダー、太陽光、電気、警報、壁パネルのノードごとに 1 枚のカードがあり、どれも同じ報告です。稼働時間、直前の再起動の理由（クラッシュやウォッチドッグは想定外と表示）、空きメモリ、回線（信号付きの Wi-Fi か有線）、ブローカーへの接続回数、最後に記録したエラー。ノードのメモリ不足、再起動の多さ、ブローカーの頻繁な切断、Wi-Fi 信号の弱さがあると、サーバーがアラームに警告を出します。「詳細」でメモリと信号の履歴と再起動を確認できます。待機中のノードはまだ報告を送っていません。古いファームウェアか、ブローカーが書き込みを許可していません。",
        "每个雷达、太阳能、电气、报警和壁挂面板节点一张卡片，格式相同：已运行多久、上次为何重启（崩溃或看门狗会标为意外）、可用内存、连接（带信号强度的 Wi-Fi 或网线）、连接代理的次数以及记录的最后一个错误。节点内存不足、重启过于频繁、反复丢失代理或 Wi-Fi 信号弱时，服务器会在“报警”中发出警告。点“详情”可看内存和信号的历史及重启记录。显示为等待中的节点尚未发送报告：固件较旧，或代理不允许其写入。",
        "Um cartão por cada nó de radar, solar, elétrico, de alarme e de painel de parede, todos com o mesmo relatório: há quanto tempo está ligado, porque reiniciou da última vez (uma falha ou um cão de guarda fica marcado como inesperado), a memória livre, a ligação (Wi-Fi com o sinal, ou o cabo), quantas vezes se ligou ao broker e o último erro que registou. O servidor levanta um aviso em Alarmes quando a um nó falta memória, reinicia demasiadas vezes, perde o broker repetidamente ou tem um sinal Wi-Fi fraco. Prima Detalhes para o histórico da memória e do sinal e os reinícios. Um nó em espera ainda não enviou relatório: tem um firmware antigo ou o broker não o deixa escrever."] },
    { target: "sys-health-control", placement: "bottom",
      t: ["Orders for the nodes", "Órdenes para los nodos", "Befehle für die Knoten", "Ordres pour les nœuds", "Ordini per i nodi", "ノードへの操作", "对节点的操作", "Ordens para os nós"],
      b: ["Orders for the nodes (administrators). In \"Health of the nodes\" each node has an Actions menu: Restart, Pause or Resume, Standby or Power on, Identify, Diagnostics and Maintenance mode. The buttons in the header give an order to all the nodes: Restart all (Now, or Rolling, which is recommended: one after another, thirty seconds apart, the alarm panel last), Pause all, Standby all and Resume all. Restart, Pause and Standby ask you to type the name of the node (or the word RESTART, PAUSE or STANDBY for all of them). A restart leaves the node unwatched for about a minute; while a node is paused (up to an hour, then it resumes by itself) or in standby, the house is NOT protected by it. Standby is work off, still connected: the node keeps answering and stays in standby after a restart until you press Power on; it is never a power-off. Maintenance mode holds back the node-offline alert for a while, and a node about to restart, update or pause announces it too: the card shows one Maintenance chip with the reason, who set it and the time left, and if the node does not return when it runs out (the server allows a node's own announcement ten minutes by default) the alerts resume and the History says the maintenance expired. Each order is followed node by node (sent, acknowledged, offline, back) and kept in the History. The server and the CM5 are never restarted this way, and nothing here resets a node to factory settings.",
        "Órdenes para los nodos (administradores). En \"Salud de los nodos\" cada nodo tiene un menú de Acciones: Reiniciar, Pausar o Reanudar, Reposo o Encender, Identificar, Diagnóstico y Modo mantenimiento. Los botones de la cabecera dan una orden a todos los nodos: Reiniciar todos (Ahora, o Escalonado, que es lo recomendado: uno tras otro, con treinta segundos entre ellos y la central de alarma la última), Pausar todos, Todos a reposo y Reanudar todos. Reiniciar, Pausar y Reposo piden escribir el nombre del nodo (o la palabra RESTART, PAUSE o STANDBY para todos). Un reinicio deja el nodo sin vigilancia cerca de un minuto; mientras un nodo está en pausa (hasta una hora, luego se reanuda solo) o en reposo, la casa NO está protegida por él. El reposo es trabajo apagado y sigue conectado: el nodo sigue respondiendo y permanece en reposo tras un reinicio hasta que pulses Encender; nunca es un apagado. El modo mantenimiento retiene un tiempo el aviso de nodo sin conexión, y un nodo que va a reiniciarse, actualizarse o pausarse también lo anuncia: la tarjeta muestra una sola etiqueta Mantenimiento con el motivo, quién la puso y el tiempo que queda, y si el nodo no vuelve cuando se acaba (el servidor concede diez minutos por defecto al anuncio de un nodo) los avisos se reanudan y el Historial dice que el mantenimiento caducó. Cada orden se sigue nodo por nodo (enviada, recibida, sin conexión, de vuelta) y queda en el Historial. El servidor y la CM5 nunca se reinician así, y nada de esto devuelve un nodo a los ajustes de fábrica.",
        "Befehle für die Knoten (Administratoren). Unter \"Zustand der Knoten\" hat jeder Knoten ein Aktionsmenü: Neu starten, Pausieren oder Fortsetzen, Standby oder Einschalten, Identifizieren, Diagnose und Wartungsmodus. Die Schaltflächen in der Kopfzeile erteilen allen Knoten einen Befehl: Alle neu starten (Jetzt oder Gestaffelt, was empfohlen wird: einer nach dem anderen, dreißig Sekunden Abstand, die Alarmzentrale zuletzt), Alle pausieren, Alle in Standby und Alle fortsetzen. Neu starten, Pausieren und Standby verlangen die Eingabe des Knotennamens (für alle das Wort RESTART, PAUSE oder STANDBY). Ein Neustart lässt den Knoten etwa eine Minute unbeaufsichtigt; solange ein Knoten pausiert (bis zu einer Stunde, dann setzt er von selbst fort) oder im Standby ist, ist das Haus durch ihn NICHT geschützt. Standby heißt Arbeit aus, weiter verbunden: Der Knoten antwortet weiter und bleibt nach einem Neustart im Standby, bis Sie Einschalten drücken; es ist nie ein Ausschalten. Der Wartungsmodus hält die Offline-Warnung eine Weile zurück, und ein Knoten, der neu startet, aktualisiert oder pausiert, kündigt das auch selbst an: Die Karte zeigt ein einziges Wartungs-Etikett mit Grund, Urheber und Restzeit, und kehrt der Knoten nach Ablauf nicht zurück (der Server erlaubt der Ankündigung eines Knotens standardmäßig zehn Minuten), setzen die Warnungen wieder ein und der Verlauf vermerkt, dass die Wartung abgelaufen ist. Jeder Befehl wird Knoten für Knoten verfolgt (gesendet, bestätigt, offline, zurück) und im Verlauf gespeichert. Server und CM5 werden so nie neu gestartet, und nichts hier setzt einen Knoten auf Werkseinstellungen zurück.",
        "Ordres pour les nœuds (administrateurs). Dans « Santé des nœuds », chaque nœud a un menu d'Actions : Redémarrer, Mettre en pause ou Reprendre, Veille ou Mettre en marche, Identifier, Diagnostic et Mode maintenance. Les boutons de l'en-tête donnent un ordre à tous les nœuds : Tout redémarrer (Maintenant, ou Échelonné, recommandé : l'un après l'autre, à trente secondes d'intervalle, la centrale d'alarme en dernier), Tout mettre en pause, Tout en veille et Tout reprendre. Redémarrer, Mettre en pause et Veille demandent de saisir le nom du nœud (ou le mot RESTART, PAUSE ou STANDBY pour tous). Un redémarrage laisse le nœud sans surveillance environ une minute ; tant qu'un nœud est en pause (jusqu'à une heure, puis il reprend tout seul) ou en veille, la maison n'est PAS protégée par lui. La veille, c'est le travail arrêté, toujours connecté : le nœud continue de répondre et reste en veille après un redémarrage jusqu'à ce que vous appuyiez sur Mettre en marche ; ce n'est jamais une mise hors tension. Le mode maintenance retient un temps l'alerte de nœud hors ligne, et un nœud sur le point de redémarrer, de se mettre à jour ou de se mettre en pause l'annonce aussi : la carte montre une seule pastille Maintenance avec la raison, qui l'a posée et le temps restant, et si le nœud ne revient pas à l'échéance (le serveur accorde dix minutes par défaut à l'annonce d'un nœud), les alertes reprennent et l'Historique indique que la maintenance a expiré. Chaque ordre est suivi nœud par nœud (envoyé, accusé de réception, hors ligne, de retour) et conservé dans l'Historique. Le serveur et la CM5 ne sont jamais redémarrés ainsi, et rien ici ne remet un nœud aux réglages d'usine.",
        "Ordini per i nodi (amministratori). In \"Salute dei nodi\" ogni nodo ha un menu Azioni: Riavvia, Metti in pausa o Riprendi, Standby o Accendi, Identifica, Diagnostica e Modalità manutenzione. I pulsanti nell'intestazione danno un ordine a tutti i nodi: Riavvia tutti (Subito, oppure Scaglionato, consigliato: uno dopo l'altro, a trenta secondi di distanza, la centrale d'allarme per ultima), Metti tutti in pausa, Tutti in standby e Riprendi tutti. Riavvia, Pausa e Standby chiedono di scrivere il nome del nodo (o la parola RESTART, PAUSE o STANDBY per tutti). Un riavvio lascia il nodo senza sorveglianza per circa un minuto; finché un nodo è in pausa (fino a un'ora, poi riprende da solo) o in standby, la casa NON è protetta da lui. Lo standby è lavoro spento ma ancora connesso: il nodo continua a rispondere e resta in standby dopo un riavvio finché non premi Accendi; non è mai uno spegnimento. La modalità manutenzione trattiene per un po' l'avviso di nodo offline, e anche un nodo che sta per riavviarsi, aggiornarsi o andare in pausa lo annuncia: la scheda mostra un'unica etichetta Manutenzione con il motivo, chi l'ha impostata e il tempo restante, e se il nodo non torna alla scadenza (il server concede dieci minuti per impostazione predefinita all'annuncio di un nodo) gli avvisi riprendono e la Cronologia indica che la manutenzione è scaduta. Ogni ordine è seguito nodo per nodo (inviato, ricevuto, offline, di nuovo online) e conservato nella Cronologia. Il server e la CM5 non vengono mai riavviati così, e nulla qui riporta un nodo alle impostazioni di fabbrica.",
        "ノードへの操作（管理者）。「ノードの状態」では各ノードに操作メニューがあります：再起動、一時停止または再開、スタンバイまたは電源オン、識別、診断、メンテナンスモード。ヘッダーのボタンはすべてのノードに操作を出します：すべて再起動（「今すぐ」または推奨の「順次」。30 秒間隔で 1 台ずつ、警報盤は最後）、すべて一時停止、すべてスタンバイ、すべて再開。再起動・一時停止・スタンバイでは、ノード名（全体の場合は RESTART、PAUSE、STANDBY のいずれか）の入力が必要です。再起動中は約 1 分間そのノードが無監視になります。ノードが一時停止中（最長 1 時間、その後は自動再開）またはスタンバイ中は、そのノードによる家の保護は行われません。スタンバイは動作オフ・接続維持の状態です。ノードは応答を続け、再起動後も「電源オン」を押すまでスタンバイのままで、電源オフではありません。メンテナンスモードは、しばらくの間ノードのオフライン警告を抑えます。再起動・更新・一時停止をするノード自身もそれを通知します。カードには理由、設定した人、残り時間を示す「メンテナンス」の表示が 1 つ出ます。期限が切れてもノードが戻らない場合（ノード自身の通知はサーバーが標準で 10 分まで認めます）、警告が再開し、履歴にメンテナンスの期限切れが記録されます。各操作はノードごとに進行（送信、受信確認、オフライン、復帰）を追跡し、履歴に残ります。サーバーと CM5 はこの方法では再起動されず、ノードを工場出荷状態に戻す操作もありません。",
        "对节点的操作（管理员）。在“节点健康状况”中，每个节点都有“操作”菜单：重启、暂停或恢复、待机或开机、识别、诊断和维护模式。标题栏中的按钮可对所有节点下达指令：全部重启（“立即”，或推荐的“依次”：每隔三十秒一个，报警主机最后）、全部暂停、全部待机和全部恢复。重启、暂停和待机需要输入节点名称（对全部节点则输入 RESTART、PAUSE 或 STANDBY）。重启会让该节点约一分钟无人监控；节点处于暂停（最长一小时，之后自动恢复）或待机时，住宅不受它保护。待机是停止工作但保持连接：节点仍会应答，重启后也保持待机，直到你点击“开机”；它绝不是关机。维护模式会在一段时间内压住节点离线警报，即将重启、更新或暂停的节点也会自行宣告：卡片上只显示一个“维护”标签，注明原因、设置者和剩余时间；到期时节点若没有回来（服务器默认只认可节点自身宣告十分钟），警报恢复，历史会注明维护已过期。每条指令都按节点跟踪（已发送、已确认、离线、已恢复）并记录在历史中。服务器和 CM5 不会以这种方式重启，这里也没有任何操作会让节点恢复出厂设置。",
        "Ordens para os nós (administradores). Em \"Saúde dos nós\" cada nó tem um menu de Ações: Reiniciar, Pausar ou Retomar, Standby ou Ligar, Identificar, Diagnóstico e Modo de manutenção. Os botões do cabeçalho dão uma ordem a todos os nós: Reiniciar todos (Agora, ou Escalonado, que é o recomendado: um após outro, com trinta segundos entre eles e a central de alarme a última), Pausar todos, Todos em standby e Retomar todos. Reiniciar, Pausar e Standby pedem que escreva o nome do nó (ou a palavra RESTART, PAUSE ou STANDBY para todos). Um reinício deixa o nó sem vigilância cerca de um minuto; enquanto um nó está em pausa (até uma hora, depois retoma sozinho) ou em standby, a casa NÃO fica protegida por ele. O standby é trabalho desligado e continua ligado: o nó continua a responder e permanece em standby após um reinício até premir Ligar; nunca é um desligar. O modo de manutenção retém durante um tempo o aviso de nó sem ligação, e um nó que vai reiniciar, atualizar-se ou pausar também o anuncia: o cartão mostra uma só etiqueta Manutenção com o motivo, quem a pôs e o tempo que resta, e se o nó não voltar quando acabar (o servidor concede dez minutos por defeito ao anúncio de um nó) os avisos retomam e o Histórico regista que a manutenção expirou. Cada ordem é seguida nó a nó (enviada, recebida, sem ligação, de volta) e fica no Histórico. O servidor e a CM5 nunca são reiniciados assim, e nada aqui repõe um nó nas definições de fábrica."] },
    { target: "sys-nodes", placement: "top",
      t: ["What the nodes send", "Lo que mandan los nodos", "Was die Knoten senden", "Ce qu'envoient les nœuds", "Cosa mandano i nodi", "ノードからの受信内容", "节点发来的内容", "O que os nós enviam"],
      b: ["Every topic the server received from the nodes: how many messages it accepted, how many it refused and why, and when the last good one arrived. A node that does not appear in its menu is explained here: its messages are being refused (a wrong field, a wrong format) or none arrive. Ignored fields and the last error are shown under the topic. The copy button puts the table on the clipboard to paste into a report.",
        "Cada tema que el servidor ha recibido de los nodos: cuántos mensajes aceptó, cuántos rechazó y por qué, y cuándo llegó el último bueno. Un nodo que no aparece en su menú se explica aquí: sus mensajes se rechazan (un campo equivocado, un formato equivocado) o no llega ninguno. Los campos ignorados y el último error se muestran bajo el tema. El botón de copiar pone la tabla en el portapapeles para pegarla en un informe.",
        "Jedes Thema, das der Server von den Knoten erhielt: wie viele Nachrichten er annahm, wie viele er ablehnte und warum, und wann die letzte gute ankam. Ein Knoten, der in seinem Menü nicht erscheint, wird hier erklärt: Seine Nachrichten werden abgelehnt (falsches Feld, falsches Format) oder es kommt keine an. Ignorierte Felder und der letzte Fehler stehen unter dem Thema. Der Kopierknopf legt die Tabelle für einen Bericht in die Zwischenablage.",
        "Chaque sujet que le serveur a reçu des nœuds : combien de messages il a acceptés, combien refusés et pourquoi, et quand le dernier bon est arrivé. Un nœud qui n'apparaît pas dans son menu s'explique ici : ses messages sont refusés (un champ erroné, un mauvais format) ou aucun n'arrive. Les champs ignorés et la dernière erreur sont affichés sous le sujet. Le bouton copier met le tableau dans le presse-papiers pour un rapport.",
        "Ogni argomento che il server ha ricevuto dai nodi: quanti messaggi ha accettato, quanti rifiutato e perché, e quando è arrivato l'ultimo buono. Un nodo che non compare nel suo menu si spiega qui: i suoi messaggi vengono rifiutati (un campo sbagliato, un formato sbagliato) o non ne arriva nessuno. I campi ignorati e l'ultimo errore sono mostrati sotto l'argomento. Il pulsante copia mette la tabella negli appunti per incollarla in un rapporto.",
        "サーバーがノードから受け取ったトピックごとに、受理したメッセージ数、拒否した数とその理由、最後に正常に届いた時刻を表示します。自分のメニューに現れないノードの理由はここで分かります。メッセージが拒否されている（フィールドや形式の誤り）か、何も届いていません。無視されたフィールドと直近のエラーはトピックの下に出ます。コピーボタンで表をクリップボードに入れ、報告書に貼れます。",
        "显示服务器从节点收到的每个主题：接受了多少条消息、拒绝了多少条及原因，以及最后一条正常消息何时到达。某个节点在自己的菜单里没出现，原因就在这里：它的消息被拒绝（字段或格式不对），或者根本没有消息到达。被忽略的字段和最后一次错误显示在主题下方。复制按钮可把表格放入剪贴板，方便粘贴到报告里。",
        "Cada tópico que o servidor recebeu dos nós: quantas mensagens aceitou, quantas recusou e porquê, e quando chegou a última boa. Um nó que não aparece no seu menu explica-se aqui: as suas mensagens estão a ser recusadas (um campo errado, um formato errado) ou não chega nenhuma. Os campos ignorados e o último erro aparecem por baixo do tópico. O botão de copiar põe a tabela na área de transferência para colar num relatório."] },
    { target: "sys-audit", placement: "top",
      t: ["The audit trail: who did what", "El registro de auditoría: quién hizo qué", "Das Audit-Protokoll: wer was tat", "Le journal d'audit : qui a fait quoi", "Il registro di audit: chi ha fatto cosa", "監査記録：誰が何をしたか", "审计记录：谁做了什么", "O registo de auditoria: quem fez o quê"],
      b: ["The list of actions taken on the system: who armed it, who changed a setting, what was denied or failed, each with the user, the target and the time. Filter it by action, user or target, or show only what was denied or failed. It is where you look when you want to know who did something. Only an administrator sees it. A run of denied logins from an address you do not know is worth a look at Security.",
        "La lista de acciones realizadas en el sistema: quién lo armó, quién cambió un ajuste, qué se denegó o falló, cada una con el usuario, el objetivo y la hora. Fíltrala por acción, usuario u objetivo, o muestra solo lo denegado o fallido. Es donde miras cuando quieres saber quién hizo algo. Solo la ve un administrador. Una racha de inicios de sesión denegados desde una dirección que no conoces merece un vistazo a Seguridad.",
        "Die Liste der am System vorgenommenen Aktionen: wer es scharf schaltete, wer eine Einstellung änderte, was verweigert wurde oder scheiterte, jeweils mit Benutzer, Ziel und Zeit. Filtern Sie nach Aktion, Benutzer oder Ziel oder zeigen Sie nur Verweigertes oder Fehlgeschlagenes. Hier schauen Sie nach, wenn Sie wissen wollen, wer etwas getan hat. Nur ein Administrator sieht sie. Eine Serie verweigerter Anmeldungen von einer unbekannten Adresse verdient einen Blick auf Sicherheit.",
        "La liste des actions menées sur le système : qui l'a armé, qui a changé un réglage, ce qui a été refusé ou a échoué, chacune avec l'utilisateur, la cible et l'heure. Filtrez par action, utilisateur ou cible, ou n'affichez que ce qui a été refusé ou a échoué. C'est là qu'on regarde pour savoir qui a fait quoi. Seul un administrateur la voit. Une série de connexions refusées depuis une adresse inconnue mérite un coup d'œil à Sécurité.",
        "L'elenco delle azioni compiute sul sistema: chi lo ha inserito, chi ha cambiato un'impostazione, cosa è stato negato o è fallito, ognuna con utente, bersaglio e ora. Filtra per azione, utente o bersaglio, oppure mostra solo ciò che è stato negato o è fallito. È dove guardi quando vuoi sapere chi ha fatto qualcosa. Lo vede solo un amministratore. Una serie di accessi negati da un indirizzo sconosciuto merita un'occhiata a Sicurezza.",
        "システムに対して行われた操作の一覧です：誰が警戒したか、誰が設定を変えたか、何が拒否・失敗したか。各行にユーザー、対象、時刻があります。操作・ユーザー・対象で絞り込め、拒否または失敗のみの表示もできます。「誰がやったか」を知りたいときに見る場所で、管理者だけが見られます。知らないアドレスからログイン拒否が続くなら、セキュリティタブを確認しましょう。",
        "这里列出对系统执行的操作：谁布了防、谁改了设置、什么被拒绝或失败了，每项都有用户、对象和时间。可按操作、用户或对象筛选，也可只看被拒绝或失败的项。想知道是谁做的某件事时就看这里。只有管理员能看到。如果出现来自陌生地址的连续登录被拒，建议去“安全”看看。",
        "A lista das ações realizadas no sistema: quem o armou, quem alterou uma definição, o que foi negado ou falhou, cada uma com o utilizador, o alvo e a hora. Filtre por ação, utilizador ou alvo, ou mostre só o negado ou falhado. É onde olha quando quer saber quem fez algo. Só um administrador a vê. Uma série de inícios de sessão negados de um endereço que não conhece merece uma vista de olhos a Segurança."] },
  ],
  services: [
    { target: "svc-stats", placement: "bottom",
      t: ["The counters of the services", "Los contadores de servicios", "Die Zähler der Dienste", "Les compteurs des services", "I contatori dei servizi", "サービスのカウンター", "服务计数器", "Os contadores dos serviços"],
      b: ["The A.R.M.O.R. programs that run on the server (the server itself, the MQTT broker, the network node, the alarm and observation services, the voice gateway and others) and the field nodes that report, active or not. The counters give the total, the active, the inactive, the failed and the others, and the number of families. A failed service is the first thing to look at when something does not work; \"Refresh\" reads the state again.",
        "Los programas de A.R.M.O.R. que se ejecutan en el servidor (el propio servidor, el broker MQTT, el nodo de red, los servicios de alarma y observación, la pasarela de voz y otros) y los nodos de campo que informan, activos o no. Los contadores dan el total, los activos, los inactivos, los fallidos y los demás, y el número de familias. Un servicio fallido es lo primero que mirar cuando algo no funciona; \"Actualizar\" vuelve a leer el estado.",
        "Die A.R.M.O.R.-Programme auf dem Server (der Server selbst, der MQTT-Broker, der Netzwerkknoten, die Alarm- und Beobachtungsdienste, das Sprach-Gateway und andere) und die berichtenden Feldknoten, aktiv oder nicht. Die Zähler zeigen Gesamt, aktiv, inaktiv, fehlgeschlagen und sonstige sowie die Zahl der Familien. Ein fehlgeschlagener Dienst ist das Erste, was man bei Störungen prüft; \"Aktualisieren\" liest den Zustand neu.",
        "Les programmes A.R.M.O.R. qui tournent sur le serveur (le serveur lui-même, le broker MQTT, le nœud réseau, les services d'alarme et d'observation, la passerelle vocale et d'autres) et les nœuds de terrain qui rapportent, actifs ou non. Les compteurs donnent le total, les actifs, les inactifs, les en échec et les autres, et le nombre de familles. Un service en échec est la première chose à regarder quand quelque chose ne marche pas ; « Actualiser » relit l'état.",
        "I programmi A.R.M.O.R. che girano sul server (il server stesso, il broker MQTT, il nodo di rete, i servizi di allarme e osservazione, il gateway vocale e altri) e i nodi di campo che riferiscono, attivi o no. I contatori danno il totale, gli attivi, gli inattivi, i falliti e gli altri, e il numero di famiglie. Un servizio fallito è la prima cosa da guardare quando qualcosa non funziona; \"Aggiorna\" rilegge lo stato.",
        "サーバー上で動く A.R.M.O.R. のプログラム（サーバー本体、MQTTブローカー、ネットワークノード、警報・観測サービス、音声ゲートウェイなど）と、報告してくる現場ノードを、稼働中かどうかにかかわらず一覧にします。カウンターは合計、稼働中、停止中、失敗、その他、ファミリー数を示します。不具合のとき最初に見るのは失敗したサービスです。「更新」で状態を再取得します。",
        "运行在服务器上的 A.R.M.O.R. 程序（服务器本体、MQTT 代理、网络节点、报警与观测服务、语音网关等）以及上报的现场节点，无论是否运行。计数器给出总数、运行中、未运行、失败、其他以及系列数。出现故障时先看失败的服务；“刷新”会重新读取状态。",
        "Os programas A.R.M.O.R. que correm no servidor (o próprio servidor, o broker MQTT, o nó de rede, os serviços de alarme e observação, a gateway de voz e outros) e os nós de campo que comunicam, ativos ou não. Os contadores dão o total, os ativos, os inativos, os falhados e os outros, e o número de famílias. Um serviço falhado é a primeira coisa a ver quando algo não funciona; \"Atualizar\" volta a ler o estado."] },
    { target: "svc-filters", placement: "bottom",
      t: ["Search and filter by family", "Buscar y filtrar por familia", "Suchen und nach Familie filtern", "Chercher et filtrer par famille", "Cercare e filtrare per famiglia", "検索とファミリーでの絞り込み", "搜索并按系列筛选", "Pesquisar e filtrar por família"],
      b: ["The search box finds a service by name. The first row of buttons shows all, only the active ones or only those that are not running; the second row filters by family (core, alarm, vision, energy, voice, network, field nodes...). Combine them to answer \"is the voice service up?\" or \"which radar nodes are silent?\" in two clicks.",
        "El buscador encuentra un servicio por nombre. La primera fila de botones muestra todos, solo los activos o solo los que no se ejecutan; la segunda filtra por familia (núcleo, alarma, visión, energía, voz, red, nodos de campo...). Combínalos para responder \"¿está activo el servicio de voz?\" o \"¿qué nodos de radar están en silencio?\" en dos clics.",
        "Die Suche findet einen Dienst per Namen. Die erste Knopfreihe zeigt alle, nur die aktiven oder nur die nicht laufenden; die zweite filtert nach Familie (Kern, Alarm, Sicht, Energie, Sprache, Netz, Feldknoten...). Kombiniert beantworten sie \"Läuft der Sprachdienst?\" oder \"Welche Radarknoten schweigen?\" in zwei Klicks.",
        "La recherche trouve un service par son nom. La première rangée de boutons montre tout, seulement les actifs ou seulement ceux qui ne tournent pas ; la seconde filtre par famille (cœur, alarme, vision, énergie, voix, réseau, nœuds de terrain...). Combinez-les pour répondre à « le service vocal est-il actif ? » ou « quels nœuds radar sont muets ? » en deux clics.",
        "La ricerca trova un servizio per nome. La prima riga di pulsanti mostra tutti, solo gli attivi o solo quelli non in esecuzione; la seconda filtra per famiglia (nucleo, allarme, visione, energia, voce, rete, nodi di campo...). Combinali per rispondere a \"il servizio vocale è attivo?\" o \"quali nodi radar sono muti?\" in due clic.",
        "検索欄で名前からサービスを探します。1段目のボタンで「すべて」「稼働中のみ」「稼働していないもののみ」、2段目でファミリー（コア、警報、ビジョン、エネルギー、音声、ネットワーク、現場ノードなど）に絞り込めます。組み合わせれば「音声サービスは動いているか」「無通信のレーダーノードはどれか」が2クリックで分かります。",
        "搜索框可按名称查找服务。第一排按钮显示全部、仅运行中或仅未运行的服务；第二排按系列筛选（核心、报警、视觉、能源、语音、网络、现场节点等）。组合使用，两次点击就能回答“语音服务在运行吗？”或“哪些雷达节点沉默了？”。",
        "A pesquisa encontra um serviço pelo nome. A primeira fila de botões mostra todos, só os ativos ou só os que não estão a correr; a segunda filtra por família (núcleo, alarme, visão, energia, voz, rede, nós de campo...). Combine-os para responder a \"o serviço de voz está ativo?\" ou \"que nós de radar estão em silêncio?\" em dois cliques."] },
    { target: "svc-grid", placement: "top",
      t: ["A service card and its buttons", "La tarjeta de un servicio y sus botones", "Die Karte eines Dienstes und ihre Knöpfe", "La carte d'un service et ses boutons", "La scheda di un servizio e i suoi pulsanti", "サービスカードとボタン", "服务卡片及其按钮", "O cartão de um serviço e os seus botões"],
      b: ["Each card shows the name, whether it is active, its family, its version and, for field nodes, when they last reported. An administrator also sees buttons to start, stop, restart, reload, pause or resume a service: Studio asks first and says what depends on it. Stopping or restarting the server leaves this console without an answer for a few seconds. Never stop the broker to \"try\": every node loses its link.",
        "Cada tarjeta muestra el nombre, si está activo, su familia, su versión y, en los nodos de campo, cuándo informaron por última vez. Un administrador ve además botones para arrancar, parar, reiniciar, recargar, pausar o reanudar un servicio: Studio pregunta antes y dice qué depende de él. Parar o reiniciar el servidor deja esta consola sin respuesta unos segundos. No pares nunca el broker \"para probar\": todos los nodos pierden su enlace.",
        "Jede Karte zeigt Name, ob aktiv, Familie, Version und bei Feldknoten, wann sie zuletzt berichteten. Ein Administrator sieht zusätzlich Knöpfe zum Starten, Stoppen, Neustarten, Neuladen, Pausieren oder Fortsetzen eines Dienstes: Studio fragt vorher und sagt, was davon abhängt. Beim Stoppen oder Neustarten des Servers antwortet diese Konsole einige Sekunden nicht. Stoppen Sie den Broker nie \"zum Testen\": Alle Knoten verlieren ihre Verbindung.",
        "Chaque carte montre le nom, s'il est actif, sa famille, sa version et, pour les nœuds de terrain, quand ils ont rapporté pour la dernière fois. Un administrateur voit aussi des boutons pour démarrer, arrêter, redémarrer, recharger, mettre en pause ou reprendre un service : Studio demande d'abord et dit ce qui en dépend. Arrêter ou redémarrer le serveur laisse cette console sans réponse quelques secondes. N'arrêtez jamais le broker « pour essayer » : tous les nœuds perdent leur lien.",
        "Ogni scheda mostra il nome, se è attivo, la famiglia, la versione e, per i nodi di campo, quando hanno riferito l'ultima volta. Un amministratore vede anche i pulsanti per avviare, fermare, riavviare, ricaricare, mettere in pausa o riprendere un servizio: Studio chiede prima e dice cosa ne dipende. Fermare o riavviare il server lascia questa console senza risposta per qualche secondo. Non fermare mai il broker \"per provare\": tutti i nodi perdono il collegamento.",
        "各カードに名前、稼働状態、ファミリー、バージョン、現場ノードなら最後の報告時刻が表示されます。管理者にはサービスの開始・停止・再起動・再読み込み・一時停止・再開ボタンも出ます。Studioが先に確認し、依存するものを知らせます。サーバーを停止または再起動すると、数秒間このコンソールは応答しません。「試しに」ブローカーを止めないでください。全ノードが接続を失います。",
        "每张卡片显示名称、是否运行、所属系列、版本，现场节点还显示最后上报时间。管理员还能看到启动、停止、重启、重载、暂停或恢复服务的按钮：Studio 会先询问并说明有什么依赖它。停止或重启服务器时，本控制台会有几秒钟没有响应。不要“试试看”就停掉代理：所有节点都会断开连接。",
        "Cada cartão mostra o nome, se está ativo, a família, a versão e, nos nós de campo, quando comunicaram pela última vez. Um administrador vê ainda botões para iniciar, parar, reiniciar, recarregar, pausar ou retomar um serviço: o Studio pergunta antes e diz o que depende dele. Parar ou reiniciar o servidor deixa esta consola sem resposta alguns segundos. Nunca pare o broker \"para experimentar\": todos os nós perdem a ligação."] },
  ],
  configuration: [
    { target: "config-tabs", placement: "bottom",
      t: ["The tabs, in groups", "Las pestañas, en grupos", "Die Reiter in Gruppen", "Les onglets, en groupes", "Le schede, in gruppi", "タブのグループ", "分组的标签页", "Os separadores, em grupos"],
      b: ["The tabs go from your own settings to the system's, with a separator between groups: General and Preferences; Users, Security, Notifications and Automatic capture; Node firmware and Updates; and Services, MQTT broker, Settings files, Installation and Console. A viewer sees only General, Users, Preferences and Security, and a tab only an administrator may use says so instead of hiding. The next steps go through them one by one.",
        "Las pestañas van de los ajustes propios a los del sistema, con un separador entre grupos: General y Preferencias; Usuarios, Seguridad, Notificaciones y Captura automática; Firmware de nodos y Actualizaciones; y Servicios, Broker MQTT, Archivos de ajustes, Instalación y Consola. Un observador solo ve General, Usuarios, Preferencias y Seguridad, y una pestaña que solo puede usar un administrador lo dice en lugar de ocultarse. Los pasos siguientes las recorren una a una.",
        "Die Reiter reichen von Ihren eigenen Einstellungen bis zu denen des Systems, mit Trennlinie zwischen den Gruppen: Allgemein und Einstellungen; Benutzer, Sicherheit, Benachrichtigungen und Automatische Aufnahme; Knoten-Firmware und Updates; sowie Dienste, MQTT-Broker, Einstellungsdateien, Installation und Konsole. Ein Betrachter sieht nur Allgemein, Benutzer, Einstellungen und Sicherheit, und ein Reiter nur für Administratoren sagt das, statt zu verschwinden. Die nächsten Schritte gehen sie einzeln durch.",
        "Les onglets vont de vos réglages à ceux du système, avec un séparateur entre groupes : Général et Préférences ; Utilisateurs, Sécurité, Notifications et Capture automatique ; Firmware des nœuds et Mises à jour ; puis Services, Broker MQTT, Fichiers de réglages, Installation et Console. Un lecteur ne voit que Général, Utilisateurs, Préférences et Sécurité, et un onglet réservé à un administrateur le dit au lieu de se cacher. Les étapes suivantes les parcourent une à une.",
        "Le schede vanno dalle tue impostazioni a quelle del sistema, con un separatore tra i gruppi: Generale e Preferenze; Utenti, Sicurezza, Notifiche e Cattura automatica; Firmware dei nodi e Aggiornamenti; e Servizi, Broker MQTT, File di impostazioni, Installazione e Console. Un osservatore vede solo Generale, Utenti, Preferenze e Sicurezza, e una scheda che può usare solo un amministratore lo dice invece di nascondersi. I passi successivi le percorrono una a una.",
        "タブは個人の設定からシステムの設定へと並び、グループ間に区切りがあります：一般と環境設定、ユーザー・セキュリティ・通知・自動キャプチャ、ノードファームウェアとアップデート、サービス・MQTTブローカー・設定ファイル・インストール・コンソール。閲覧者には一般・ユーザー・環境設定・セキュリティだけが見え、管理者専用のタブはその旨が表示されます。以降のステップで1つずつ説明します。",
        "标签页从个人设置排到系统设置，组与组之间有分隔线：常规和偏好设置；用户、安全、通知和自动抓拍；节点固件和更新；服务、MQTT 代理、设置文件、安装和控制台。查看者只能看到常规、用户、偏好设置和安全，仅管理员可用的标签页会说明这一点而不是隐藏。后面的步骤会逐个讲解。",
        "Os separadores vão das suas definições às do sistema, com uma separação entre grupos: Geral e Preferências; Utilizadores, Segurança, Notificações e Captura automática; Firmware dos nós e Atualizações; e Serviços, Broker MQTT, Ficheiros de definições, Instalação e Consola. Um observador só vê Geral, Utilizadores, Preferências e Segurança, e um separador que só um administrador pode usar di-lo em vez de se esconder. Os passos seguintes percorrem-nos um a um."] },
    { target: "tab-general", placement: "bottom",
      t: ["General: server address, ports and look", "General: dirección del servidor, puertos y aspecto", "Allgemein: Serveradresse, Ports und Aussehen", "Général : adresse du serveur, ports et aspect", "Generale: indirizzo del server, porte e aspetto", "一般：サーバーアドレス・ポート・外観", "常规：服务器地址、端口与外观", "Geral: endereço do servidor, portas e aspeto"],
      b: ["Three cards, each saying where it applies. The address Studio uses to talk to the ARMOR server (with a button to check it) is kept in this browser only: another computer or phone has its own. Where the server listens and where Studio is served is for the whole server (administrators only) and takes effect the next time they start. Interface sets the theme and the language, only for you. Mistake: a wrong address logs you out of everything; check it before saving.",
        "Tres tarjetas, cada una diciendo dónde se aplica. La dirección que usa Studio para hablar con el servidor ARMOR (con un botón para comprobarla) se guarda solo en este navegador: otro ordenador o móvil tiene la suya. Dónde escucha el servidor y dónde se sirve Studio vale para todo el servidor (solo administradores) y se aplica la próxima vez que arranquen. Interfaz fija el tema y el idioma, solo para ti. Error: una dirección equivocada te saca de todo; compruébala antes de guardar.",
        "Drei Karten, jede mit Angabe, wo sie gilt. Die Adresse, über die Studio mit dem ARMOR-Server spricht (mit Prüfknopf), wird nur in diesem Browser gespeichert: ein anderer Rechner oder ein Handy hat seine eigene. Wo der Server lauscht und wo Studio ausgeliefert wird, gilt für den ganzen Server (nur Administratoren) und greift beim nächsten Start. Oberfläche setzt Design und Sprache, nur für Sie. Fehler: Eine falsche Adresse wirft Sie überall raus - prüfen Sie sie vor dem Speichern.",
        "Trois cartes, chacune disant où elle s'applique. L'adresse que Studio utilise pour parler au serveur ARMOR (avec un bouton pour la vérifier) n'est conservée que dans ce navigateur : un autre ordinateur ou téléphone a la sienne. Où le serveur écoute et où Studio est servi vaut pour tout le serveur (administrateurs seulement) et s'applique au prochain démarrage. Interface règle le thème et la langue, pour vous seul. Erreur : une mauvaise adresse vous déconnecte de tout, vérifiez-la avant d'enregistrer.",
        "Tre schede, ognuna dice dove si applica. L'indirizzo che Studio usa per parlare con il server ARMOR (con un pulsante per verificarlo) è conservato solo in questo browser: un altro computer o telefono ha il suo. Dove ascolta il server e dove viene servito Studio vale per tutto il server (solo amministratori) e si applica al prossimo avvio. Interfaccia imposta tema e lingua, solo per te. Errore: un indirizzo sbagliato ti butta fuori da tutto; verificalo prima di salvare.",
        "3枚のカードがあり、それぞれ適用範囲が書かれています。Studioが ARMOR サーバーと通信するアドレス（確認ボタン付き）はこのブラウザーだけに保存され、別のPCやスマホには別の値があります。サーバーの待ち受け先とStudioの配信先はサーバー全体の設定（管理者のみ）で、次回の起動時に反映されます。インターフェースのテーマと言語はあなた専用です。アドレスを誤ると全部ログアウトされるので、保存前に確認しましょう。",
        "三张卡片，每张都说明作用范围。Studio 连接 ARMOR 服务器所用的地址（带检查按钮）只保存在此浏览器中：另一台电脑或手机有它自己的地址。服务器监听位置和 Studio 的提供位置作用于整个服务器（仅管理员），下次启动时生效。界面卡片设置主题和语言，仅对你自己有效。错误提示：地址写错会让你全部退出，保存前先检查。",
        "Três cartões, cada um a dizer onde se aplica. O endereço que o Studio usa para falar com o servidor ARMOR (com um botão para o verificar) guarda-se só neste navegador: outro computador ou telemóvel tem o seu. Onde o servidor escuta e onde o Studio é servido vale para todo o servidor (só administradores) e aplica-se no próximo arranque. Interface define o tema e o idioma, só para si. Erro: um endereço errado tira-o de tudo; verifique-o antes de guardar."] },
    { target: "tab-preferences", placement: "bottom",
      t: ["Preferences: tours, hints, sounds and the assistant", "Preferencias: guías, ayudas, sonidos y el asistente", "Einstellungen: Touren, Hinweise, Töne und der Assistent", "Préférences : guides, bulles, sons et l'assistant", "Preferenze: guide, suggerimenti, suoni e l'assistente", "環境設定：ツアー・ヒント・サウンド・アシスタント", "偏好设置：导览、提示、声音和助手", "Preferências: guias, dicas, sons e o assistente"],
      b: ["How Studio helps you, how it looks and moves, where it opens and how it announces alarms; kept in this browser, so a phone and a desk can differ. The step-by-step tours (a welcome tour and one per menu, with their mascot and voice), the hover hints (off, text, or with an animated picture and the time they wait), animations, density, text size, the menu Studio opens at, the sounds, voice and pop-ups for each kind and severity of alarm with a play button to hear them, and the assistant (pin it, its size, its bubble).",
        "Cómo te ayuda Studio, cómo se ve y se mueve, dónde abre y cómo anuncia las alarmas; se guarda en este navegador, así que un móvil y un ordenador pueden diferir. Las guías paso a paso (una de bienvenida y una por menú, con su mascota y voz), los globos al pasar el puntero (apagados, texto, o con imagen animada y el tiempo que esperan), las animaciones, la densidad, el tamaño del texto, el menú en el que abre Studio, los sonidos, la voz y los avisos de cada tipo y gravedad de alarma con un botón de reproducir para oírlos, y el asistente (fijarlo, su tamaño, su globo).",
        "Wie Studio Ihnen hilft, wie es aussieht und sich bewegt, wo es öffnet und wie es Alarme ansagt; im Browser gespeichert, sodass Handy und Schreibtisch abweichen können. Die Schritt-für-Schritt-Touren (eine Willkommenstour und eine pro Menü, mit Maskottchen und Stimme), die Hinweise beim Überfahren (aus, Text oder mit animiertem Bild und Wartezeit), Animationen, Dichte, Textgröße, das Startmenü, die Töne, Stimme und Pop-ups je Alarmart und Schweregrad mit Abspielknopf zum Anhören sowie der Assistent (anheften, Größe, Sprechblase).",
        "Comment Studio vous aide, son aspect et ses mouvements, où il s'ouvre et comment il annonce les alarmes ; conservé dans ce navigateur, donc un téléphone et un bureau peuvent différer. Les guides pas à pas (un de bienvenue et un par menu, avec leur mascotte et voix), les bulles au survol (désactivées, texte, ou avec image animée et le délai), les animations, la densité, la taille du texte, le menu d'ouverture, les sons, la voix et les fenêtres pour chaque type et gravité d'alarme avec un bouton lecture pour les entendre, et l'assistant (l'épingler, sa taille, sa bulle).",
        "Come ti aiuta Studio, come appare e si muove, dove si apre e come annuncia gli allarmi; conservate in questo browser, quindi telefono e scrivania possono differire. Le guide passo passo (una di benvenuto e una per menu, con mascotte e voce), i suggerimenti al passaggio (spenti, testo, o con immagine animata e il tempo di attesa), le animazioni, la densità, la dimensione del testo, il menu di apertura, i suoni, la voce e le finestre per ogni tipo e gravità di allarme con un pulsante play per ascoltarli, e l'assistente (fissarlo, dimensione, fumetto).",
        "Studioがどう手助けし、どう見えどう動き、どのメニューで開き、アラームをどう知らせるかを設定します。設定はこのブラウザーに保存されるので、スマホとPCで異なる設定にできます。ステップバイステップのツアー（ようこそツアーと各メニュー用、マスコットと音声付き）、ホバーヒント（オフ・テキスト・アニメ画像付きと待ち時間）、アニメーション、密度、文字サイズ、起動メニュー、アラームの種類と重大度ごとの音・音声・ポップアップ（再生ボタンで試聴）、アシスタント（固定、サイズ、吹き出し）。",
        "设置 Studio 如何帮助你、外观与动效、打开时的菜单以及如何播报报警；保存在此浏览器中，因此手机和台式机可以不同。包括分步导览（欢迎导览和每个菜单一个，带吉祥物和语音）、悬停提示（关闭、文字，或带动画图片及等待时间）、动画、密度、文字大小、启动菜单、按报警类型和严重程度设置的声音、语音和弹窗（有播放按钮可试听），以及助手（固定、大小、气泡）。",
        "Como o Studio o ajuda, o aspeto e o movimento, onde abre e como anuncia os alarmes; guardadas neste navegador, por isso um telemóvel e uma secretária podem diferir. As visitas guiadas (uma de boas-vindas e uma por menu, com mascote e voz), as dicas ao passar o ponteiro (desligadas, texto, ou com imagem animada e o tempo de espera), as animações, a densidade, o tamanho do texto, o menu de abertura, os sons, a voz e os avisos de cada tipo e gravidade de alarme com um botão de reproduzir para os ouvir, e o assistente (fixá-lo, tamanho, balão)."] },
    { target: "tab-users", placement: "bottom",
      t: ["Users, roles and PINs", "Usuarios, roles y PIN", "Benutzer, Rollen und PINs", "Utilisateurs, rôles et PIN", "Utenti, ruoli e PIN", "ユーザー・ロール・PIN", "用户、角色与 PIN", "Utilizadores, funções e PIN"],
      b: ["Who can sign in to Studio. There are three roles: an administrator changes everything including users; an operator answers alarms, sees the cameras and arms and disarms; a viewer (family, guards) only looks and cannot arm, acknowledge, switch, delete or change anything. Each user can have a PIN of 4 to 10 digits to disarm and an optional duress PIN that disarms but silently raises a critical alarm. \"My account\" lets anyone change their own password (the current one is required). Give each person their own account: the audit trail then says who did what.",
        "Quién puede entrar en Studio. Hay tres roles: un administrador cambia todo, incluidos los usuarios; un operador atiende las alarmas, ve las cámaras y arma y desarma; un observador (familia, vigilantes) solo mira y no puede armar, reconocer, conmutar, borrar ni cambiar nada. Cada usuario puede tener un PIN de 4 a 10 dígitos para desarmar y un PIN de coacción opcional que desarma pero avisa en silencio con una alarma crítica. \"Mi cuenta\" deja a cualquiera cambiar su contraseña (hace falta la actual). Da a cada persona su propia cuenta: así el registro de auditoría dice quién hizo qué.",
        "Wer sich in Studio anmelden darf. Es gibt drei Rollen: Ein Administrator ändert alles, auch Benutzer; ein Bediener beantwortet Alarme, sieht die Kameras und schaltet scharf und unscharf; ein Betrachter (Familie, Wachleute) sieht nur und kann nichts scharf schalten, quittieren, schalten, löschen oder ändern. Jeder Benutzer kann eine PIN mit 4 bis 10 Ziffern zum Unscharfschalten und eine optionale Nötigungs-PIN haben, die unscharf schaltet, aber still einen kritischen Alarm auslöst. \"Mein Konto\" lässt jeden das eigene Passwort ändern (das aktuelle ist nötig). Geben Sie jeder Person ein eigenes Konto: Das Audit-Protokoll sagt dann, wer was tat.",
        "Qui peut se connecter à Studio. Il y a trois rôles : un administrateur change tout, y compris les utilisateurs ; un opérateur répond aux alarmes, voit les caméras et arme et désarme ; un lecteur (famille, gardiens) ne fait que regarder et ne peut ni armer, ni acquitter, ni commuter, ni supprimer, ni changer quoi que ce soit. Chaque utilisateur peut avoir un PIN de 4 à 10 chiffres pour désarmer et un PIN de contrainte facultatif qui désarme mais lève en silence une alarme critique. « Mon compte » permet à chacun de changer son mot de passe (l'actuel est requis). Donnez à chaque personne son compte : le journal d'audit dit alors qui a fait quoi.",
        "Chi può accedere a Studio. Ci sono tre ruoli: un amministratore cambia tutto, utenti compresi; un operatore risponde agli allarmi, vede le telecamere e inserisce e disinserisce; un osservatore (famiglia, guardie) può solo guardare e non può inserire, riconoscere, commutare, eliminare né cambiare nulla. Ogni utente può avere un PIN da 4 a 10 cifre per disinserire e un PIN di coercizione facoltativo che disinserisce ma solleva in silenzio un allarme critico. \"Il mio account\" permette a chiunque di cambiare la propria password (serve quella attuale). Dai a ogni persona un account proprio: il registro di audit dice poi chi ha fatto cosa.",
        "Studioにログインできる人を管理します。ロールは3つ：管理者はユーザーを含むすべてを変更でき、オペレーターはアラーム対応・カメラ閲覧・警戒と解除ができ、閲覧者（家族、警備員）は見るだけで、警戒・確認・切替・削除・変更はできません。各ユーザーは解除用の4〜10桁のPINと、解除はできるが静かに重大アラームを上げる強要PIN（任意）を持てます。「マイアカウント」では誰でも自分のパスワードを変更できます（現在のパスワードが必要）。人ごとにアカウントを作れば、監査記録で誰が何をしたか分かります。",
        "管理谁可以登录 Studio。有三种角色：管理员可更改一切，包括用户；操作员处理报警、查看摄像头并布防撤防；查看者（家人、保安）只能查看，不能布防、确认、切换、删除或更改任何内容。每个用户可设置 4 到 10 位的撤防 PIN，以及可选的胁迫 PIN（同样撤防，但会悄悄触发严重报警）。“我的账户”让任何人更改自己的密码（需要当前密码）。给每个人单独的账户，审计记录才能说明谁做了什么。",
        "Quem pode entrar no Studio. Há três funções: um administrador altera tudo, incluindo utilizadores; um operador atende os alarmes, vê as câmaras e arma e desarma; um observador (família, vigilantes) só olha e não pode armar, reconhecer, comutar, apagar nem alterar nada. Cada utilizador pode ter um PIN de 4 a 10 dígitos para desarmar e um PIN de coação opcional que desarma mas avisa em silêncio com um alarme crítico. \"A minha conta\" deixa qualquer um alterar a sua palavra-passe (é preciso a atual). Dê a cada pessoa a sua conta: assim o registo de auditoria diz quem fez o quê."] },
    { target: "tab-security", placement: "bottom",
      t: ["Security: second factor, sessions and outside access", "Seguridad: segundo factor, sesiones y acceso desde fuera", "Sicherheit: zweiter Faktor, Sitzungen, Zugriff von außen", "Sécurité : second facteur, sessions et accès extérieur", "Sicurezza: secondo fattore, sessioni e accesso da fuori", "セキュリティ：二要素認証・セッション・外部アクセス", "安全：二步验证、会话与外部访问", "Segurança: segundo fator, sessões e acesso exterior"],
      b: ["Your account: set up the second factor with your password, add the key to an authenticator app, confirm with the first code and keep the ten recovery codes shown once. Open sessions lists every browser or phone signed in; end the ones you do not recognise. \"How the server sees you\" says whether you count as the house or outside: try it from a phone on mobile data before relying on outside access. An administrator also sets the trusted proxy, the VPN, what a session from outside may do and, in \"Reaching the house from outside\", the VPN with phone QR codes, a dynamic name and the panels of the nodes; its guide shows six steps and which are done.",
        "Tu cuenta: configura el segundo factor con tu contraseña, añade la clave a una app de autenticación, confirma con el primer código y guarda los diez códigos de recuperación, que se muestran una vez. Sesiones abiertas lista cada navegador o móvil con sesión; cierra las que no reconozcas. \"Cómo te ve el servidor\" dice si cuentas como la casa o como fuera: pruébalo desde un móvil con datos antes de fiarte del acceso exterior. Un administrador fija también el proxy de confianza, la VPN, lo que puede hacer una sesión desde fuera y, en \"Llegar a la casa desde fuera\", la VPN con códigos QR para móviles, un nombre dinámico y los paneles de los nodos; su guía muestra seis pasos y cuáles están hechos.",
        "Ihr Konto: Richten Sie den zweiten Faktor mit Ihrem Passwort ein, fügen Sie den Schlüssel einer Authenticator-App hinzu, bestätigen Sie mit dem ersten Code und bewahren Sie die zehn einmalig gezeigten Wiederherstellungscodes auf. Offene Sitzungen listet jeden angemeldeten Browser oder jedes Handy; beenden Sie unbekannte. \"Wie der Server Sie sieht\" sagt, ob Sie als Haus oder von außen gelten: Probieren Sie es mit einem Handy im Mobilfunk, bevor Sie sich auf den Zugriff von außen verlassen. Ein Administrator legt zudem Proxy, VPN, die Rechte einer Sitzung von außen und unter \"Das Haus von außen erreichen\" das VPN mit QR-Codes für Handys, einen dynamischen Namen und die Panels der Knoten fest; die Anleitung zeigt sechs Schritte und welche erledigt sind.",
        "Votre compte : configurez le second facteur avec votre mot de passe, ajoutez la clé à une application d'authentification, confirmez avec le premier code et gardez les dix codes de secours montrés une seule fois. Sessions ouvertes liste chaque navigateur ou téléphone connecté ; fermez celles que vous ne reconnaissez pas. « Comment le serveur vous voit » dit si vous comptez comme la maison ou l'extérieur : essayez depuis un téléphone en données mobiles avant de vous fier à l'accès extérieur. Un administrateur règle aussi le proxy de confiance, le VPN, ce qu'une session extérieure peut faire et, dans « Joindre la maison de l'extérieur », le VPN avec codes QR pour téléphones, un nom dynamique et les panneaux des nœuds ; son guide montre six étapes et lesquelles sont faites.",
        "Il tuo account: imposta il secondo fattore con la password, aggiungi la chiave a un'app di autenticazione, conferma con il primo codice e conserva i dieci codici di recupero mostrati una sola volta. Sessioni aperte elenca ogni browser o telefono connesso; chiudi quelle che non riconosci. \"Come ti vede il server\" dice se conti come la casa o come fuori: provalo da un telefono con dati mobili prima di fidarti dell'accesso dall'esterno. Un amministratore imposta anche il proxy fidato, la VPN, cosa può fare una sessione da fuori e, in \"Raggiungere la casa da fuori\", la VPN con codici QR per i telefoni, un nome dinamico e i pannelli dei nodi; la sua guida mostra sei passi e quali sono fatti.",
        "あなたのアカウント：パスワードで二要素認証を設定し、認証アプリにキーを追加して最初のコードで確認し、1度だけ表示される10個のリカバリーコードを保管します。「開いているセッション」はログイン中のブラウザーやスマホを一覧にし、覚えのないものは終了できます。「サーバーからの見え方」は、家内として扱われるか外部かを示します。外部アクセスに頼る前に、モバイルデータのスマホで試してください。管理者は信頼プロキシ、VPN、外部セッションの権限、さらに「家に外から入る」でVPN（スマホ用QRコード付き）、動的DNS名、ノードのパネル中継を設定します。ガイドは6つの手順と完了状況を表示します。",
        "你的账户：用密码设置二步验证，把密钥添加到验证器应用，用第一个验证码确认，并保存只显示一次的十个恢复码。“已登录的会话”列出每个已登录的浏览器或手机，可结束你不认识的会话。“服务器如何看到你”会说明你被视为住宅内部还是外部：依赖外部访问之前，请先用使用移动数据的手机试试。管理员还可设置可信代理、VPN、外部会话的权限，并在“从外部访问住宅”中设置带手机二维码的 VPN、动态域名和节点面板；其向导显示六个步骤及完成情况。",
        "A sua conta: configure o segundo fator com a palavra-passe, adicione a chave a uma app de autenticação, confirme com o primeiro código e guarde os dez códigos de recuperação mostrados uma só vez. Sessões abertas lista cada navegador ou telemóvel com sessão; termine as que não reconhece. \"Como o servidor o vê\" diz se conta como a casa ou como fora: experimente a partir de um telemóvel com dados móveis antes de confiar no acesso exterior. Um administrador define também o proxy de confiança, a VPN, o que uma sessão de fora pode fazer e, em \"Chegar à casa de fora\", a VPN com códigos QR para telemóveis, um nome dinâmico e os painéis dos nós; o seu guia mostra seis passos e quais estão feitos."] },
    { target: "tab-notifications", placement: "bottom",
      t: ["Notifications: where alarms are sent", "Notificaciones: adónde se envían las alarmas", "Benachrichtigungen: wohin Alarme gehen", "Notifications : où partent les alarmes", "Notifiche: dove vanno gli allarmi", "通知：アラームの送り先", "通知：报警发往何处", "Notificações: para onde vão os alarmes"],
      b: ["Besides the notifications of the phone app and the history, the server can send every alarm to a Telegram chat and to Home Assistant, and always publishes it on MQTT. This tab shows which places are set up and sends a test message to each, so a wrong token or address shows up now and not on the night of an alarm. In ntfy, a push goes to the phone's ntfy app (the highest priority for a critical alarm, sounding even in silent mode), and a critical alarm nobody acknowledges within the set minutes is told again as unattended to every channel.",
        "Además de las notificaciones de la app del móvil y del historial, el servidor puede enviar cada alarma a un chat de Telegram y a Home Assistant, y siempre la publica en MQTT. Esta pestaña muestra qué lugares están configurados y envía un mensaje de prueba a cada uno, para que un token o una dirección equivocados se vean ahora y no la noche de una alarma. En ntfy, un aviso llega a la app ntfy del móvil (la máxima prioridad para una alarma crítica, que suena incluso en silencio), y una alarma crítica que nadie reconoce en los minutos fijados se vuelve a comunicar como desatendida a todos los canales.",
        "Neben den Benachrichtigungen der Handy-App und dem Verlauf kann der Server jeden Alarm an einen Telegram-Chat und an Home Assistant senden und veröffentlicht ihn immer auf MQTT. Dieser Reiter zeigt, welche Ziele eingerichtet sind, und sendet an jedes eine Testnachricht, damit ein falscher Token oder eine falsche Adresse jetzt auffällt und nicht in der Alarmnacht. Bei ntfy geht ein Push an die ntfy-App (höchste Priorität bei kritischem Alarm, auch im Lautlos-Modus hörbar), und ein kritischer Alarm, den niemand in den eingestellten Minuten quittiert, wird als unbeachtet an alle Kanäle erneut gemeldet.",
        "Outre les notifications de l'application mobile et l'historique, le serveur peut envoyer chaque alarme à un chat Telegram et à Home Assistant, et la publie toujours sur MQTT. Cet onglet montre quels endroits sont configurés et envoie un message de test à chacun, pour qu'un jeton ou une adresse erronés se voient maintenant et pas la nuit d'une alarme. Avec ntfy, une notification part vers l'appli ntfy du téléphone (priorité maximale pour une alarme critique, qui sonne même en silencieux), et une alarme critique que personne n'acquitte dans les minutes réglées est redite comme non traitée sur tous les canaux.",
        "Oltre alle notifiche dell'app del telefono e alla cronologia, il server può inviare ogni allarme a una chat Telegram e a Home Assistant, e lo pubblica sempre su MQTT. Questa scheda mostra quali destinazioni sono configurate e invia un messaggio di prova a ciascuna, così un token o un indirizzo sbagliati si vedono ora e non la notte di un allarme. Con ntfy, una notifica arriva all'app ntfy del telefono (priorità massima per un allarme critico, che suona anche in silenzioso), e un allarme critico che nessuno riconosce entro i minuti impostati viene ripetuto come non gestito su tutti i canali.",
        "スマホアプリの通知と履歴のほかに、サーバーはすべてのアラームをTelegramチャットとHome Assistantに送れ、常にMQTTにも発行します。このタブは設定済みの送り先を示し、それぞれにテストメッセージを送れるので、トークンやアドレスの間違いをアラームの夜ではなく今見つけられます。ntfyはスマホのntfyアプリにプッシュを送り（重大アラームは最高優先度でサイレントでも鳴動）、設定した分数以内に誰も確認しなかった重大アラームは、未対応として全チャンネルへ再通知されます。",
        "除手机应用的通知和历史外，服务器还可把每条报警发到 Telegram 聊天和 Home Assistant，并且始终发布到 MQTT。此标签页显示已配置的去向，并可向每一处发送测试消息，这样错误的令牌或地址现在就能发现，而不是在报警那天晚上。使用 ntfy 时，推送会发到手机的 ntfy 应用（严重报警为最高优先级，静音下也会响），若严重报警在设定的分钟内无人确认，会作为无人处理再次通知所有渠道。",
        "Além das notificações da app do telemóvel e do histórico, o servidor pode enviar cada alarme para um chat do Telegram e para o Home Assistant, e publica-o sempre em MQTT. Este separador mostra que destinos estão configurados e envia uma mensagem de teste a cada um, para um token ou endereço errado se ver agora e não na noite de um alarme. No ntfy, um aviso vai para a app ntfy do telemóvel (prioridade máxima para um alarme crítico, que toca mesmo em silêncio), e um alarme crítico que ninguém reconhece nos minutos definidos é comunicado de novo como não atendido a todos os canais."] },
    { target: "tab-capture", placement: "bottom",
      t: ["Automatic capture", "Captura automática", "Automatische Aufnahme", "Capture automatique", "Cattura automatica", "自動キャプチャ", "自动抓拍", "Captura automática"],
      b: ["What the server takes by itself when a camera sees something while the perimeter is armed. Turn it on or off, choose whether it takes photos and how many (up to 60, one to 300 seconds apart), whether it records and for how many seconds (3 to 300), and how long a camera is left alone after a capture (5 seconds to an hour) so that someone walking in front of it does not fill the disk. The latest captures are listed on the right and live in Recordings. Anyone who may look sees the values; an administrator sets them.",
        "Lo que toma el servidor por sí solo cuando una cámara ve algo con el perímetro armado. Actívala o desactívala, elige si hace fotos y cuántas (hasta 60, con uno a 300 segundos entre ellas), si graba y cuántos segundos (3 a 300), y cuánto se deja en paz a una cámara tras una captura (5 segundos a una hora) para que alguien que pasa delante no llene el disco. Las últimas capturas se listan a la derecha y viven en Grabaciones. Quien puede mirar ve los valores; un administrador los fija.",
        "Was der Server selbst aufnimmt, wenn eine Kamera bei scharfem Perimeter etwas sieht. Ein- oder ausschalten, wählen, ob Fotos gemacht werden und wie viele (bis 60, im Abstand von 1 bis 300 Sekunden), ob aufgezeichnet wird und wie viele Sekunden (3 bis 300), und wie lange eine Kamera nach einer Aufnahme in Ruhe gelassen wird (5 Sekunden bis eine Stunde), damit jemand, der vorbeiläuft, nicht die Platte füllt. Die letzten Aufnahmen stehen rechts und liegen unter Aufnahmen. Wer schauen darf, sieht die Werte; ein Administrator stellt sie ein.",
        "Ce que le serveur prend seul quand une caméra voit quelque chose, périmètre armé. Activez ou désactivez, choisissez s'il prend des photos et combien (jusqu'à 60, espacées de 1 à 300 secondes), s'il enregistre et combien de secondes (3 à 300), et combien de temps on laisse une caméra tranquille après une capture (5 secondes à une heure) pour que quelqu'un qui passe devant ne remplisse pas le disque. Les dernières captures sont listées à droite et vivent dans Enregistrements. Qui peut regarder voit les valeurs ; un administrateur les règle.",
        "Ciò che il server prende da solo quando una telecamera vede qualcosa a perimetro inserito. Attivala o disattivala, scegli se scatta foto e quante (fino a 60, a distanza di 1-300 secondi), se registra e per quanti secondi (da 3 a 300), e per quanto si lascia in pace una telecamera dopo una cattura (da 5 secondi a un'ora) perché chi passa davanti non riempia il disco. Le ultime catture sono elencate a destra e stanno in Registrazioni. Chi può guardare vede i valori; un amministratore li imposta.",
        "警戒中にカメラが何かを捉えたとき、サーバーが自動で保存するものの設定です。オン／オフ、写真を撮るか（最大60枚、1〜300秒間隔）、録画するか（3〜300秒）、キャプチャ後にそのカメラを休ませる時間（5秒〜1時間。前を通っただけでディスクが埋まらないようにするため）を選びます。最新のキャプチャは右に並び、録画ライブラリにも保存されます。閲覧できる人は値を確認でき、設定は管理者が行います。",
        "设置周界布防时摄像头发现情况后服务器自动保存的内容。可开关该功能，选择是否拍照及张数（最多 60 张，间隔 1 到 300 秒）、是否录像及时长（3 到 300 秒），以及抓拍后让该摄像头静默多久（5 秒到一小时），避免有人在镜头前走过就把磁盘填满。最新的抓拍列在右侧，也保存在“录像”中。有权查看的人能看到这些值，管理员负责设置。",
        "O que o servidor tira por si quando uma câmara vê algo com o perímetro armado. Ative-a ou desative-a, escolha se tira fotos e quantas (até 60, com 1 a 300 segundos entre elas), se grava e quantos segundos (3 a 300), e quanto tempo se deixa em paz uma câmara após uma captura (5 segundos a uma hora) para quem passa à frente não encher o disco. As últimas capturas listam-se à direita e ficam em Gravações. Quem pode olhar vê os valores; um administrador define-os."] },
    { target: "tab-firmware", placement: "bottom",
      t: ["Node firmware: update many nodes safely", "Firmware de nodos: actualizar muchos nodos con seguridad", "Knoten-Firmware: viele Knoten sicher aktualisieren", "Firmware des nœuds : mettre à jour en sécurité", "Firmware dei nodi: aggiornare molti nodi in sicurezza", "ノードファームウェア：安全に一括更新", "节点固件：安全地批量更新", "Firmware dos nós: atualizar vários nós em segurança"],
      b: ["Update the firmware of the field nodes (radar, solar, electrical, alarm and touch panel) without opening the page of each one: from a file of this computer or from the newest release on GitHub, which the server downloads and checks against the hash the release publishes. The node installs it in its spare firmware slot and only switches over if the image is valid; if the new one does not start, it goes back to the previous one. Releases are signed: a node refuses an image without a valid signature, and a file you upload by hand in its panel is still accepted. Send to one node or to every node of a type, one after another, with the login of the nodes' own panel (used for this update only, never kept). A node the network node does not see can be added by its address, and the update asks for your password again when you are outside the house.",
        "Actualiza el firmware de los nodos de campo (radar, solar, eléctrico, alarma y panel táctil) sin abrir la página de cada uno: desde un archivo de este ordenador o desde la última versión en GitHub, que el servidor descarga y comprueba con el hash que publica la versión. El nodo la instala en su ranura de firmware libre y solo cambia si la imagen es válida; si la nueva no arranca, vuelve a la anterior. Las versiones están firmadas: un nodo rechaza una imagen sin firma válida, y un archivo que subas a mano en su panel sigue aceptándose. Envía a un nodo o a todos los de un tipo, uno tras otro, con el acceso del panel propio de los nodos (se usa solo para esta actualización, nunca se guarda). Un nodo que el nodo de red no ve se puede añadir por su dirección, y la actualización vuelve a pedir tu contraseña si estás fuera de casa.",
        "Aktualisieren Sie die Firmware der Feldknoten (Radar, Solar, Elektrik, Alarm und Touch-Panel), ohne die Seite jedes Knotens zu öffnen: aus einer Datei dieses Rechners oder aus dem neuesten Release auf GitHub, das der Server lädt und gegen den vom Release veröffentlichten Hash prüft. Der Knoten installiert sie in seinem freien Firmware-Slot und schaltet nur um, wenn das Abbild gültig ist; startet das neue nicht, kehrt er zum vorigen zurück. Releases sind signiert: Ein Knoten lehnt ein Abbild ohne gültige Signatur ab, eine von Hand im Panel hochgeladene Datei wird weiter akzeptiert. Senden Sie an einen Knoten oder an alle eines Typs nacheinander, mit dem Login des Knoten-Panels (nur für dieses Update, nie gespeichert). Ein Knoten, den der Netzwerkknoten nicht sieht, lässt sich per Adresse hinzufügen, und das Update verlangt außerhalb des Hauses erneut Ihr Passwort.",
        "Mettez à jour le firmware des nœuds de terrain (radar, solaire, électrique, alarme et écran tactile) sans ouvrir la page de chacun : depuis un fichier de cet ordinateur ou depuis la dernière version sur GitHub, que le serveur télécharge et vérifie avec le hash publié par la version. Le nœud l'installe dans son emplacement de firmware libre et ne bascule que si l'image est valide ; si la nouvelle ne démarre pas, il revient à la précédente. Les versions sont signées : un nœud refuse une image sans signature valide, et un fichier envoyé à la main dans son panneau reste accepté. Envoyez à un nœud ou à tous ceux d'un type, l'un après l'autre, avec l'identifiant du panneau des nœuds (utilisé pour cette mise à jour seulement, jamais conservé). Un nœud que le nœud réseau ne voit pas peut être ajouté par son adresse, et la mise à jour redemande votre mot de passe hors de la maison.",
        "Aggiorna il firmware dei nodi di campo (radar, solare, elettrico, allarme e pannello touch) senza aprire la pagina di ognuno: da un file di questo computer o dall'ultima versione su GitHub, che il server scarica e controlla con l'hash pubblicato dalla versione. Il nodo la installa nel suo slot firmware libero e commuta solo se l'immagine è valida; se la nuova non parte, torna alla precedente. Le versioni sono firmate: un nodo rifiuta un'immagine senza firma valida, e un file caricato a mano nel suo pannello è comunque accettato. Invia a un nodo o a tutti di un tipo, uno dopo l'altro, con il login del pannello dei nodi (usato solo per questo aggiornamento, mai conservato). Un nodo che il nodo di rete non vede si aggiunge dal suo indirizzo, e l'aggiornamento richiede di nuovo la tua password se sei fuori casa.",
        "現場ノード（レーダー、ソーラー、電気、警報、タッチパネル）のファームウェアを、各ノードのページを開かずに更新します。このPCのファイルか、GitHubの最新リリースを使い、リリースが公開するハッシュでサーバーが検証します。ノードは空いている側のファームウェアスロットに書き込み、イメージが有効なときだけ切り替えます。新しい版が起動しなければ前の版へ戻ります。リリースは署名付きで、有効な署名のないイメージはノードが拒否しますが、パネルで手動アップロードしたファイルは受け付けます。1台、または種類ごとの全ノードへ順に送信でき、ノード自身のパネルのログインを使います（この更新のみ・保存なし）。ネットワークノードから見えないノードはアドレスで追加でき、家の外からでは更新時にパスワードを再度求められます。",
        "无需逐个打开节点页面，即可更新现场节点（雷达、太阳能、电气、报警和触摸屏）的固件：使用本机文件，或使用 GitHub 上的最新版本，由服务器下载并用版本公布的哈希校验。节点把它安装到备用的固件分区，仅当镜像有效时才切换；若新版本无法启动，则回到旧版本。版本带有签名：节点会拒绝没有有效签名的镜像，而你在其面板里手动上传的文件仍会被接受。可发送给一个节点或某一类型的全部节点，依次进行，使用节点自己面板的登录信息（仅用于本次更新，从不保存）。网络节点看不到的节点可按地址添加，在住宅外更新时会再次要求输入密码。",
        "Atualize o firmware dos nós de campo (radar, solar, elétrico, alarme e painel tátil) sem abrir a página de cada um: a partir de um ficheiro deste computador ou da versão mais recente no GitHub, que o servidor descarrega e verifica com o hash que a versão publica. O nó instala-o na sua ranhura de firmware livre e só muda se a imagem for válida; se a nova não arrancar, volta à anterior. As versões são assinadas: um nó recusa uma imagem sem assinatura válida, e um ficheiro carregado à mão no seu painel continua a ser aceite. Envie para um nó ou para todos de um tipo, um a seguir ao outro, com o acesso do painel próprio dos nós (usado só para esta atualização, nunca guardado). Um nó que o nó de rede não vê pode ser adicionado pelo endereço, e a atualização pede de novo a sua palavra-passe quando está fora de casa."] },
    { target: "tab-batteries", placement: "bottom",
      t: ["Battery maintenance: write to a Pylontech battery, with care", "Mantenimiento de baterías: escribir en una batería Pylontech, con cuidado", "Batteriewartung: in eine Pylontech-Batterie schreiben, mit Vorsicht", "Maintenance des batteries : écrire dans une batterie Pylontech, avec précaution", "Manutenzione delle batterie: scrivere su una batteria Pylontech, con cautela", "バッテリーメンテナンス：Pylontechバッテリーへの書き込み（慎重に）", "电池维护：谨慎地向 Pylontech 电池写入", "Manutenção de baterias: escrever numa bateria Pylontech, com cuidado"],
      b: ["For administrators. A guided screen in four steps to change what a Pylontech battery keeps, as the maker's own tool does, through the gateway node it is plugged into. 1, Battery and operation: choose the node, its port (1 to 10) and the operation - the clock, the statistics counters and logs, restarting or shutting down, the charge level (SOC) and the capacity, the limits and protections, the outputs, the memory and serial number, or a firmware file. 2, Values: limits are typed in volts and degrees, a whole group at a time, and checked against the ranges and the order between values that the maker's tool states. 3, Confirm: the node first logs in and reads the battery, and the screen shows exactly what it will do, with the battery's model, serial number and firmware and the risk; to go on you type the serial number exactly as the battery reports it (a wrong port or a wrong battery is caught here) and your password or second factor, also inside the house. 4, Result: what changed, read back from the battery, with the history of operations (who ordered what, when and how it ended) and, for an output switched by mistake, a button to put it back as it was. Writing is off in the server until ARMOR_BATTERY_WRITE=1 is set. Switching a protection off needs a tick that says you understand the risk, a firmware file (.bin) is read first (board, version, size and SHA-256 are shown) and the node refuses one that does not fit the battery's model and chip, and an operation cannot be stopped once it has started.",
        "Para administradores. Una pantalla guiada en cuatro pasos para cambiar lo que guarda una batería Pylontech, como hace la herramienta del propio fabricante, a través del nodo pasarela al que está conectada. 1, Batería y operación: elige el nodo, su puerto (1 a 10) y la operación: el reloj, los contadores de estadísticas y los registros, reiniciar o apagar, el nivel de carga (SOC) y la capacidad, los límites y las protecciones, las salidas, la memoria y el número de serie, o un archivo de firmware. 2, Valores: los límites se escriben en voltios y grados, un grupo entero cada vez, y se comprueban contra los rangos y el orden entre valores que indica la herramienta del fabricante. 3, Confirmar: el nodo primero entra y lee la batería, y la pantalla muestra exactamente lo que hará, con el modelo, el número de serie y el firmware de la batería y el riesgo; para seguir escribes el número de serie tal como lo informa la batería (aquí se descubre un puerto o una batería equivocados) y tu contraseña o segundo factor, también dentro de casa. 4, Resultado: qué cambió, releído de la batería, con el historial de operaciones (quién ordenó qué, cuándo y cómo acabó) y, para una salida conmutada por error, un botón para dejarla como estaba. La escritura está apagada en el servidor hasta que se ponga ARMOR_BATTERY_WRITE=1. Desactivar una protección exige una casilla que diga que entiendes el riesgo, un archivo de firmware (.bin) se lee primero (se muestran placa, versión, tamaño y SHA-256) y el nodo rechaza el que no encaja con el modelo y el chip de la batería, y una operación no se puede detener una vez empezada.",
        "Für Administratoren. Ein geführter Bildschirm in vier Schritten, um zu ändern, was eine Pylontech-Batterie speichert, wie es das Werkzeug des Herstellers tut, über den Gateway-Knoten, an dem sie angeschlossen ist. 1, Batterie und Operation: Knoten, Port (1 bis 10) und Operation wählen - die Uhr, die Statistikzähler und Protokolle, Neustart oder Ausschalten, Ladezustand (SOC) und Kapazität, Grenzwerte und Schutzfunktionen, Ausgänge, Speicher und Seriennummer oder eine Firmware-Datei. 2, Werte: Grenzwerte werden in Volt und Grad eingegeben, eine ganze Gruppe auf einmal, und gegen die Bereiche und die Reihenfolge der Werte geprüft, die das Herstellerwerkzeug vorgibt. 3, Bestätigen: Der Knoten meldet sich zuerst an und liest die Batterie, und der Bildschirm zeigt genau, was er tun wird, mit Modell, Seriennummer und Firmware der Batterie und dem Risiko; zum Fortfahren geben Sie die Seriennummer genau so ein, wie die Batterie sie meldet (ein falscher Port oder eine falsche Batterie fällt hier auf), und Ihr Passwort oder den zweiten Faktor, auch im Haus. 4, Ergebnis: was sich geändert hat, aus der Batterie zurückgelesen, mit dem Verlauf der Operationen (wer was wann angeordnet hat und wie es endete) und, für einen versehentlich geschalteten Ausgang, einer Schaltfläche, um ihn zurückzusetzen. Das Schreiben ist im Server aus, bis ARMOR_BATTERY_WRITE=1 gesetzt ist. Das Abschalten eines Schutzes verlangt ein Häkchen, dass Sie das Risiko verstehen, eine Firmware-Datei (.bin) wird zuerst gelesen (Platine, Version, Größe und SHA-256 werden angezeigt) und der Knoten lehnt eine ab, die nicht zu Modell und Chip der Batterie passt, und eine begonnene Operation lässt sich nicht mehr anhalten.",
        "Pour les administrateurs. Un écran guidé en quatre étapes pour changer ce que retient une batterie Pylontech, comme le fait l'outil du fabricant, via le nœud passerelle auquel elle est branchée. 1, Batterie et opération : choisissez le nœud, son port (1 à 10) et l'opération - l'horloge, les compteurs de statistiques et les journaux, le redémarrage ou l'arrêt, le niveau de charge (SOC) et la capacité, les limites et protections, les sorties, la mémoire et le numéro de série, ou un fichier de firmware. 2, Valeurs : les limites se saisissent en volts et en degrés, un groupe entier à la fois, et sont vérifiées selon les plages et l'ordre entre valeurs qu'indique l'outil du fabricant. 3, Confirmer : le nœud se connecte d'abord et lit la batterie, et l'écran montre exactement ce qu'il va faire, avec le modèle, le numéro de série et le firmware de la batterie et le risque ; pour continuer, vous saisissez le numéro de série exactement comme la batterie le déclare (un mauvais port ou une mauvaise batterie est détecté ici) et votre mot de passe ou second facteur, même dans la maison. 4, Résultat : ce qui a changé, relu dans la batterie, avec l'historique des opérations (qui a ordonné quoi, quand et comment cela s'est terminé) et, pour une sortie commutée par erreur, un bouton pour la remettre comme avant. L'écriture est désactivée dans le serveur tant que ARMOR_BATTERY_WRITE=1 n'est pas défini. Désactiver une protection exige une case disant que vous comprenez le risque, un fichier de firmware (.bin) est lu d'abord (carte, version, taille et SHA-256 sont affichés) et le nœud refuse celui qui ne convient pas au modèle et à la puce de la batterie, et une opération ne peut pas être arrêtée une fois commencée.",
        "Per gli amministratori. Una schermata guidata in quattro passi per cambiare ciò che conserva una batteria Pylontech, come fa lo strumento del produttore, tramite il nodo gateway a cui è collegata. 1, Batteria e operazione: scegli il nodo, la sua porta (da 1 a 10) e l'operazione - l'orologio, i contatori statistici e i registri, il riavvio o lo spegnimento, il livello di carica (SOC) e la capacità, i limiti e le protezioni, le uscite, la memoria e il numero di serie, o un file di firmware. 2, Valori: i limiti si scrivono in volt e gradi, un gruppo intero alla volta, e vengono verificati secondo gli intervalli e l'ordine tra i valori che indica lo strumento del produttore. 3, Conferma: il nodo prima accede e legge la batteria, e la schermata mostra esattamente cosa farà, con modello, numero di serie e firmware della batteria e il rischio; per proseguire scrivi il numero di serie esattamente come lo dichiara la batteria (qui si scopre una porta o una batteria sbagliata) e la tua password o secondo fattore, anche in casa. 4, Risultato: cosa è cambiato, riletto dalla batteria, con lo storico delle operazioni (chi ha ordinato cosa, quando e come è finita) e, per un'uscita commutata per errore, un pulsante per rimetterla com'era. La scrittura è disattivata nel server finché non si imposta ARMOR_BATTERY_WRITE=1. Disattivare una protezione richiede una spunta che dica che capisci il rischio, un file di firmware (.bin) si legge prima (si mostrano scheda, versione, dimensione e SHA-256) e il nodo rifiuta quello che non è adatto al modello e al chip della batteria, e un'operazione non si può fermare una volta iniziata.",
        "管理者向けです。Pylontechバッテリーが保持する内容を、メーカー純正ツールと同じように、接続先のゲートウェイノード経由で変更する4ステップのガイド画面です。1、バッテリーと操作：ノード、そのポート（1〜10）、操作（時計、統計カウンターとログ、再起動または停止、充電レベル（SOC）と容量、制限と保護、出力、メモリとシリアル番号、またはファームウェアファイル）を選びます。2、値：制限はボルトと度で、グループ単位でまとめて入力し、メーカーのツールが示す範囲と値の順序に照らして検査されます。3、確認：ノードが先にログインしてバッテリーを読み取り、画面にはバッテリーのモデル・シリアル番号・ファームウェアとリスクとともに、実行する内容がそのまま表示されます。続行するには、バッテリーが報告するとおりにシリアル番号を入力し（ポートやバッテリーの取り違えはここで分かります）、パスワードまたは第二要素を入力します（家の中でも必要です）。4、結果：バッテリーから読み戻した変更内容と操作履歴（誰が何をいつ命じ、どう終わったか）が表示され、誤って切り替えた出力には元に戻すボタンがあります。書き込みは、サーバーでARMOR_BATTERY_WRITE=1を設定するまで無効です。保護を無効にするにはリスクを理解したことを示すチェックが必要で、ファームウェアファイル（.bin）は先に読み取られ（基板・バージョン・サイズ・SHA-256を表示）、バッテリーのモデルとチップに合わないものはノードが拒否し、始まった操作は止められません。",
        "仅限管理员。这是一个分四步的引导界面，通过电池所接的网关节点，像厂家自带工具那样修改 Pylontech 电池保存的内容。1、电池与操作：选择节点、其端口（1 至 10）和操作——时钟、统计计数器与日志、重启或关机、电量（SOC）与容量、限值与保护、输出、存储器与序列号，或固件文件。2、数值：限值以伏特和摄氏度输入，每次整组提交，并按厂家工具规定的范围和数值之间的顺序检查。3、确认：节点先登录并读取电池，界面会准确显示它将做什么，以及电池的型号、序列号、固件和风险；要继续，需按电池上报的内容原样输入序列号（端口或电池选错会在这里被发现），并输入你的密码或第二重验证，在家里也一样。4、结果：从电池读回的变化，以及操作历史（谁在何时下达了什么、结果如何）；对误切换的输出，有按钮可恢复原状。服务器上写入默认关闭，直到设置 ARMOR_BATTERY_WRITE=1。关闭保护需要勾选表示你了解风险；固件文件（.bin）会先被读取（显示主板、版本、大小和 SHA-256），不适合该电池型号和芯片的文件会被节点拒绝；操作一旦开始就无法停止。",
        "Para administradores. Um ecrã guiado em quatro passos para alterar o que guarda uma bateria Pylontech, como faz a ferramenta do próprio fabricante, através do nó gateway a que está ligada. 1, Bateria e operação: escolha o nó, a sua porta (1 a 10) e a operação - o relógio, os contadores de estatísticas e os registos, reiniciar ou desligar, o nível de carga (SOC) e a capacidade, os limites e as proteções, as saídas, a memória e o número de série, ou um ficheiro de firmware. 2, Valores: os limites escrevem-se em volts e graus, um grupo inteiro de cada vez, e são verificados face aos intervalos e à ordem entre valores que a ferramenta do fabricante indica. 3, Confirmar: o nó começa por iniciar sessão e ler a bateria, e o ecrã mostra exatamente o que vai fazer, com o modelo, o número de série e o firmware da bateria e o risco; para continuar escreve o número de série exatamente como a bateria o comunica (aqui descobre-se uma porta ou uma bateria errada) e a sua palavra-passe ou segundo fator, também dentro de casa. 4, Resultado: o que mudou, relido da bateria, com o histórico das operações (quem ordenou o quê, quando e como acabou) e, para uma saída comutada por engano, um botão para a deixar como estava. A escrita está desligada no servidor até se definir ARMOR_BATTERY_WRITE=1. Desativar uma proteção exige uma caixa que diga que compreende o risco, um ficheiro de firmware (.bin) é lido primeiro (mostram-se placa, versão, tamanho e SHA-256) e o nó recusa o que não encaixa no modelo e no chip da bateria, e uma operação não se pode parar depois de começar."] },
    { target: "tab-updates", placement: "bottom",
      t: ["Updates of this machine", "Actualizaciones de esta máquina", "Updates dieser Maschine", "Mises à jour de cette machine", "Aggiornamenti di questa macchina", "このマシンのアップデート", "本机的更新", "Atualizações desta máquina"],
      b: ["What is installed here against the newest release of each program on GitHub, plus the updates of the operating system. Choose what to update, or update everything; the release notes of a new version are shown before you install it. Each update is checked against the hash the release publishes, keeps a copy of what it replaces and puts it back if the program does not work afterwards. \"Check\" asks GitHub again. Do it when nothing important is happening: updating the server cuts this console for a few seconds.",
        "Lo instalado aquí frente a la última versión publicada de cada programa en GitHub, y las actualizaciones del sistema operativo. Elige qué actualizar, o actualiza todo; las notas de la versión nueva se muestran antes de instalar. Cada actualización se comprueba con el hash que publica la versión, guarda una copia de lo que sustituye y lo devuelve si el programa no funciona después. \"Comprobar\" vuelve a preguntar a GitHub. Hazlo cuando no pase nada importante: actualizar el servidor corta esta consola unos segundos.",
        "Das hier Installierte gegenüber dem neuesten Release jedes Programms auf GitHub sowie die Updates des Betriebssystems. Wählen Sie, was aktualisiert wird, oder aktualisieren Sie alles; die Release-Hinweise einer neuen Version werden vor der Installation gezeigt. Jedes Update wird gegen den vom Release veröffentlichten Hash geprüft, sichert eine Kopie des Ersetzten und stellt sie wieder her, wenn das Programm danach nicht läuft. \"Prüfen\" fragt GitHub erneut. Tun Sie es, wenn nichts Wichtiges läuft: Das Server-Update unterbricht diese Konsole einige Sekunden.",
        "Ce qui est installé ici face à la dernière version de chaque programme sur GitHub, plus les mises à jour du système d'exploitation. Choisissez quoi mettre à jour, ou tout ; les notes de la nouvelle version s'affichent avant l'installation. Chaque mise à jour est vérifiée avec le hash publié par la version, garde une copie de ce qu'elle remplace et la remet si le programme ne fonctionne pas ensuite. « Vérifier » interroge de nouveau GitHub. Faites-le quand rien d'important ne se passe : mettre à jour le serveur coupe cette console quelques secondes.",
        "Ciò che è installato qui rispetto all'ultima versione di ogni programma su GitHub, più gli aggiornamenti del sistema operativo. Scegli cosa aggiornare, o aggiorna tutto; le note della nuova versione si mostrano prima di installare. Ogni aggiornamento è verificato con l'hash pubblicato dalla versione, conserva una copia di ciò che sostituisce e la rimette se il programma non funziona dopo. \"Controlla\" interroga di nuovo GitHub. Fallo quando non succede nulla di importante: aggiornare il server interrompe questa console per qualche secondo.",
        "ここにインストールされているものを、GitHubの各プログラムの最新リリースと比べ、OSのアップデートも合わせて表示します。更新するものを選ぶか、すべて更新できます。新バージョンのリリースノートはインストール前に表示されます。各更新はリリースが公開するハッシュで検証され、置き換えるものを保存し、更新後にプログラムが動かなければ元に戻します。「確認」でGitHubに再問い合わせします。重要な作業中は避けてください。サーバーの更新ではこのコンソールが数秒切れます。",
        "显示本机已安装的内容与 GitHub 上各程序最新版本的对比，以及操作系统的更新。可选择要更新的项目，也可全部更新；新版本的发布说明会在安装前显示。每次更新都会用版本公布的哈希校验，保留被替换内容的副本，并在程序随后无法运行时恢复。“检查”会再次询问 GitHub。请在没有重要事情时更新：更新服务器会让本控制台中断几秒。",
        "O que está instalado aqui face à versão mais recente de cada programa no GitHub, mais as atualizações do sistema operativo. Escolha o que atualizar, ou atualize tudo; as notas da versão nova mostram-se antes de instalar. Cada atualização é verificada com o hash que a versão publica, guarda uma cópia do que substitui e devolve-o se o programa não funcionar depois. \"Verificar\" volta a perguntar ao GitHub. Faça-o quando não estiver a acontecer nada importante: atualizar o servidor corta esta consola alguns segundos."] },
    { target: "tab-services", placement: "bottom",
      t: ["Services tab: start, stop and restart", "Pestaña Servicios: arrancar, parar y reiniciar", "Reiter Dienste: starten, stoppen, neu starten", "Onglet Services : démarrer, arrêter, redémarrer", "Scheda Servizi: avviare, fermare, riavviare", "サービスタブ：開始・停止・再起動", "服务标签页：启动、停止与重启", "Separador Serviços: iniciar, parar e reiniciar"],
      b: ["Start, stop or restart each system service. Stopping one makes what depends on it stop working until it is started again; Studio asks before it does and says what depends on it. This is where you restart the server after changing its settings, or a stuck service. The Services menu in the Administration group only looks; this tab acts. Never stop the broker or the server without need.",
        "Arranca, para o reinicia cada servicio del sistema. Parar uno hace que lo que depende de él deje de funcionar hasta que se arranque de nuevo; Studio pregunta antes y dice qué depende de él. Aquí reinicias el servidor tras cambiar sus ajustes, o un servicio atascado. El menú Servicios del grupo Administración solo mira; esta pestaña actúa. No pares el broker ni el servidor sin necesidad.",
        "Starten, stoppen oder neu starten Sie jeden Systemdienst. Das Stoppen eines Dienstes lässt alles, was davon abhängt, ausfallen, bis er wieder startet; Studio fragt vorher und sagt, was davon abhängt. Hier starten Sie den Server nach geänderten Einstellungen oder einen hängenden Dienst neu. Das Menü Dienste der Gruppe Administration schaut nur; dieser Reiter handelt. Stoppen Sie Broker oder Server nicht ohne Not.",
        "Démarrez, arrêtez ou redémarrez chaque service du système. En arrêter un fait que ce qui en dépend cesse de fonctionner jusqu'à son redémarrage ; Studio demande d'abord et dit ce qui en dépend. C'est ici que vous redémarrez le serveur après avoir changé ses réglages, ou un service bloqué. Le menu Services du groupe Administration ne fait que regarder ; cet onglet agit. N'arrêtez le broker ni le serveur sans nécessité.",
        "Avvia, ferma o riavvia ogni servizio del sistema. Fermarne uno fa smettere di funzionare ciò che ne dipende finché non lo riavvii; Studio chiede prima e dice cosa ne dipende. Qui riavvii il server dopo aver cambiato le sue impostazioni, o un servizio bloccato. Il menu Servizi del gruppo Amministrazione si limita a guardare; questa scheda agisce. Non fermare il broker né il server senza necessità.",
        "システムの各サービスを開始・停止・再起動します。1つを止めると、それに依存するものは再開するまで動かなくなります。Studioが先に確認し、依存先を知らせます。設定変更後のサーバー再起動や、固まったサービスの再起動はここで行います。管理グループの「サービス」メニューは見るだけで、このタブが操作します。必要がなければブローカーやサーバーを止めないでください。",
        "启动、停止或重启每个系统服务。停止某个服务会让依赖它的内容停止工作，直到它再次启动；Studio 会先询问并说明有什么依赖它。修改服务器设置后重启服务器，或重启卡住的服务，都在这里。管理组里的“服务”菜单只查看，这个标签页才执行操作。没有必要不要停止代理或服务器。",
        "Inicie, pare ou reinicie cada serviço do sistema. Parar um faz com que o que depende dele deixe de funcionar até ser iniciado de novo; o Studio pergunta antes e diz o que depende dele. É aqui que reinicia o servidor depois de alterar as suas definições, ou um serviço preso. O menu Serviços do grupo Administração só olha; este separador atua. Não pare o broker nem o servidor sem necessidade."] },
    { target: "tab-broker", placement: "bottom",
      t: ["MQTT broker: the accounts of the nodes", "Broker MQTT: las cuentas de los nodos", "MQTT-Broker: die Konten der Knoten", "Broker MQTT : les comptes des nœuds", "Broker MQTT: gli account dei nodi", "MQTTブローカー：ノードのアカウント", "MQTT 代理：节点账户", "Broker MQTT: as contas dos nós"],
      b: ["The broker is where every node and the server meet. Start, stop or restart it here, give each node, device or consumer its own account (which can only read and write its own topics) and edit its settings and permissions below. The password is shown once, when the account is made: copy it into the node's panel at once. One account per node means a lost or stolen node can be cut off without touching the others. Never publish the broker to the Internet.",
        "El broker es donde se encuentran todos los nodos y el servidor. Arráncalo, páralo o reinícialo aquí, da a cada nodo, dispositivo o consumidor su propia cuenta (que solo puede leer y escribir sus propios topics) y edita abajo sus ajustes y permisos. La contraseña se muestra una vez, al crear la cuenta: cópiala enseguida en el panel del nodo. Una cuenta por nodo permite cortar un nodo perdido o robado sin tocar los demás. No publiques nunca el broker en Internet.",
        "Der Broker ist der Treffpunkt aller Knoten und des Servers. Starten, stoppen oder starten Sie ihn hier neu, geben Sie jedem Knoten, Gerät oder Verbraucher ein eigenes Konto (das nur seine eigenen Topics lesen und schreiben darf) und bearbeiten Sie unten Einstellungen und Berechtigungen. Das Passwort wird einmal beim Anlegen gezeigt: Kopieren Sie es sofort ins Panel des Knotens. Ein Konto je Knoten erlaubt, einen verlorenen oder gestohlenen Knoten zu sperren, ohne die anderen anzutasten. Veröffentlichen Sie den Broker nie im Internet.",
        "Le broker est le lieu de rencontre de tous les nœuds et du serveur. Démarrez, arrêtez ou redémarrez-le ici, donnez à chaque nœud, appareil ou consommateur son propre compte (qui ne peut lire et écrire que ses propres topics) et modifiez dessous ses réglages et permissions. Le mot de passe s'affiche une fois, à la création du compte : copiez-le tout de suite dans le panneau du nœud. Un compte par nœud permet de couper un nœud perdu ou volé sans toucher aux autres. Ne publiez jamais le broker sur Internet.",
        "Il broker è dove si incontrano tutti i nodi e il server. Avvialo, fermalo o riavvialo qui, dai a ogni nodo, dispositivo o consumatore il suo account (che può leggere e scrivere solo i propri topic) e modifica sotto le sue impostazioni e i permessi. La password si mostra una volta, quando si crea l'account: copiala subito nel pannello del nodo. Un account per nodo permette di tagliare fuori un nodo perso o rubato senza toccare gli altri. Non pubblicare mai il broker su Internet.",
        "ブローカーは、すべてのノードとサーバーが出会う場所です。ここで開始・停止・再起動し、ノード・デバイス・利用者ごとに専用アカウント（自分のトピックだけ読み書き可能）を作り、下で設定と権限を編集します。パスワードはアカウント作成時に1度だけ表示されるので、すぐノードのパネルにコピーしてください。ノードごとにアカウントを分けておけば、紛失や盗難のノードだけを他に影響なく遮断できます。ブローカーをインターネットに公開してはいけません。",
        "代理是所有节点与服务器的汇合点。可在此启动、停止或重启它，为每个节点、设备或消费者建立独立账户（只能读写自己的主题），并在下方编辑其设置和权限。密码仅在创建账户时显示一次：请立即复制到节点的面板里。每个节点一个账户，丢失或被盗的节点就能单独断开而不影响其他节点。切勿把代理发布到互联网。",
        "O broker é onde todos os nós e o servidor se encontram. Inicie-o, pare-o ou reinicie-o aqui, dê a cada nó, dispositivo ou consumidor a sua conta (que só pode ler e escrever os seus próprios tópicos) e edite em baixo as suas definições e permissões. A palavra-passe mostra-se uma vez, ao criar a conta: copie-a de imediato para o painel do nó. Uma conta por nó permite cortar um nó perdido ou roubado sem tocar nos outros. Nunca publique o broker na Internet."] },
    { target: "tab-files", placement: "bottom",
      t: ["Settings files of the system", "Archivos de ajustes del sistema", "Einstellungsdateien des Systems", "Fichiers de réglages du système", "File di impostazioni del sistema", "システムの設定ファイル", "系统设置文件", "Ficheiros de definições do sistema"],
      b: ["Every settings file of A.R.M.O.R. on this machine, to read and change without looking for it by hand. Secrets stay hidden: a field that holds a password or token is shown masked and keeps its value unless you type a new one. Each save keeps a copy of the previous file, so a mistake can be undone. A bad value in a settings file can stop a service from starting: change one thing at a time and restart that service from the Services tab to check.",
        "Todos los archivos de ajustes de A.R.M.O.R. de esta máquina, para leerlos y cambiarlos sin buscarlos a mano. Los secretos quedan ocultos: un campo que guarda una contraseña o token se muestra enmascarado y conserva su valor salvo que escribas uno nuevo. Cada guardado conserva una copia del archivo anterior, así que un error se puede deshacer. Un valor malo en un archivo de ajustes puede impedir que un servicio arranque: cambia una cosa cada vez y reinicia ese servicio desde la pestaña Servicios para comprobarlo.",
        "Jede Einstellungsdatei von A.R.M.O.R. auf dieser Maschine, zum Lesen und Ändern ohne Suchen von Hand. Geheimnisse bleiben verborgen: Ein Feld mit Passwort oder Token wird maskiert gezeigt und behält seinen Wert, bis Sie einen neuen eingeben. Jedes Speichern behält eine Kopie der vorigen Datei, sodass sich ein Fehler rückgängig machen lässt. Ein falscher Wert kann einen Dienst am Start hindern: Ändern Sie eins nach dem anderen und starten Sie den Dienst im Reiter Dienste neu, um es zu prüfen.",
        "Chaque fichier de réglages d'A.R.M.O.R. sur cette machine, à lire et modifier sans le chercher à la main. Les secrets restent cachés : un champ contenant un mot de passe ou jeton s'affiche masqué et garde sa valeur sauf si vous en saisissez une nouvelle. Chaque enregistrement garde une copie du fichier précédent, une erreur peut donc être annulée. Une mauvaise valeur peut empêcher un service de démarrer : changez une chose à la fois et redémarrez ce service depuis l'onglet Services pour vérifier.",
        "Ogni file di impostazioni di A.R.M.O.R. su questa macchina, da leggere e modificare senza cercarlo a mano. I segreti restano nascosti: un campo con password o token è mostrato mascherato e conserva il valore salvo che ne scrivi uno nuovo. Ogni salvataggio conserva una copia del file precedente, così un errore si può annullare. Un valore sbagliato può impedire l'avvio di un servizio: cambia una cosa alla volta e riavvia quel servizio dalla scheda Servizi per verificare.",
        "このマシン上の A.R.M.O.R. のすべての設定ファイルを、手で探さずに閲覧・変更できます。秘密情報は隠されます：パスワードやトークンのフィールドはマスク表示で、新しい値を入力しない限り元の値が保たれます。保存のたびに直前のファイルのコピーが残るので、間違いは元に戻せます。設定値の誤りでサービスが起動しなくなることがあります。1つずつ変更し、サービスタブでそのサービスを再起動して確認してください。",
        "本机上 A.R.M.O.R. 的所有设置文件，无需手动寻找即可查看和修改。机密信息保持隐藏：保存密码或令牌的字段以掩码显示，除非输入新值否则保持原值。每次保存都会保留前一份文件的副本，因此错误可以撤销。设置值不对可能导致服务无法启动：一次只改一项，并到“服务”标签页重启该服务来验证。",
        "Todos os ficheiros de definições do A.R.M.O.R. desta máquina, para ler e alterar sem os procurar à mão. Os segredos ficam escondidos: um campo que guarda uma palavra-passe ou token mostra-se mascarado e mantém o valor a não ser que escreva um novo. Cada gravação guarda uma cópia do ficheiro anterior, por isso um erro pode ser desfeito. Um valor mau pode impedir um serviço de arrancar: altere uma coisa de cada vez e reinicie esse serviço no separador Serviços para verificar."] },
    { target: "tab-diagnostics", placement: "bottom",
      t: ["Diagnostics: a package from a node, and read-only access for somebody else", "Diagnóstico: un paquete de un nodo y acceso de solo lectura para otra persona", "Diagnose: ein Paket von einem Knoten und Lesezugriff für eine andere Person", "Diagnostic : un paquet d'un nœud et un accès en lecture seule pour quelqu'un d'autre", "Diagnostica: un pacchetto da un nodo e accesso in sola lettura per un'altra persona", "診断：ノードのパッケージと、他の人への読み取り専用アクセス", "诊断：节点的诊断包，以及给他人的只读访问", "Diagnóstico: um pacote de um nó e acesso só de leitura para outra pessoa"],
      b: ["For administrators. At the top, what a token can and cannot do: it only reads the health, the diagnostic package and the log of the nodes you choose, it can never give an order, it expires by itself and you can revoke it at any moment. To issue one, tick the nodes, pick the duration (2 hours by default) and write who it is for; Studio asks for your password again and shows the token once, with a Copy button: it cannot be seen again. Below, the list shows each token with its nodes, its state, when it expires, how many times it was used and when last. At the bottom, pick a node and ask it for its diagnostic package or its log: you read why it last started, its memory, the tasks with the least stack, the memory gate, the core dump and the settings it allows to be read, and you can download them.",
        "Para administradores. Arriba, lo que un token puede y no puede hacer: solo lee la salud, el paquete de diagnóstico y el registro de los nodos que elijas, nunca puede dar una orden, caduca solo y puedes revocarlo en cualquier momento. Para emitir uno, marca los nodos, elige la duración (2 horas por defecto) y escribe para quién es; Studio te pide la contraseña de nuevo y muestra el token una sola vez, con un botón Copiar: no se puede volver a ver. Debajo, la lista muestra cada token con sus nodos, su estado, cuándo caduca, cuántas veces se usó y cuándo fue la última. Abajo, elige un nodo y pídele su paquete de diagnóstico o su registro: lees por qué arrancó la última vez, su memoria, las tareas con menos pila, la puerta de memoria, el volcado de núcleo y los ajustes que permite leer, y puedes descargarlos.",
        "Für Administratoren. Oben steht, was ein Token kann und was nicht: Es liest nur Zustand, Diagnosepaket und Protokoll der gewählten Knoten, kann nie einen Befehl geben, läuft von selbst ab und lässt sich jederzeit widerrufen. Zum Ausstellen haken Sie die Knoten an, wählen die Dauer (standardmäßig 2 Stunden) und notieren, für wen es ist; Studio fragt erneut nach Ihrem Passwort und zeigt das Token nur einmal mit einer Schaltfläche Kopieren: Es lässt sich nicht erneut anzeigen. Darunter listet die Liste jedes Token mit seinen Knoten, seinem Zustand, dem Ablauf, der Zahl der Nutzungen und der letzten Nutzung. Unten wählen Sie einen Knoten und fordern sein Diagnosepaket oder sein Protokoll an: Sie lesen, warum er zuletzt gestartet ist, seinen Speicher, die Tasks mit dem wenigsten Stack, das Speichertor, den Core-Dump und die lesbaren Einstellungen und können alles herunterladen.",
        "Pour les administrateurs. En haut, ce qu'un jeton peut et ne peut pas faire : il lit seulement la santé, le paquet de diagnostic et le journal des nœuds choisis, ne peut jamais donner un ordre, expire de lui-même et se révoque à tout moment. Pour en émettre un, cochez les nœuds, choisissez la durée (2 heures par défaut) et écrivez pour qui il est ; Studio redemande votre mot de passe et affiche le jeton une seule fois, avec un bouton Copier : on ne peut plus le revoir. Dessous, la liste montre chaque jeton avec ses nœuds, son état, son expiration, le nombre d'utilisations et la dernière. En bas, choisissez un nœud et demandez-lui son paquet de diagnostic ou son journal : vous lisez pourquoi il a démarré la dernière fois, sa mémoire, les tâches avec le moins de pile, la porte de mémoire, le vidage du cœur et les réglages qu'il laisse lire, et vous pouvez les télécharger.",
        "Per gli amministratori. In alto, cosa può e non può fare un token: legge solo la salute, il pacchetto di diagnostica e il registro dei nodi scelti, non può mai dare un ordine, scade da solo e si revoca in qualsiasi momento. Per emetterne uno, spunta i nodi, scegli la durata (2 ore per impostazione predefinita) e scrivi per chi è; Studio chiede di nuovo la password e mostra il token una sola volta, con un pulsante Copia: non si può rivedere. Sotto, l'elenco mostra ogni token con i suoi nodi, lo stato, la scadenza, quante volte è stato usato e l'ultima volta. In basso, scegli un nodo e chiedigli il pacchetto di diagnostica o il registro: leggi perché si è avviato l'ultima volta, la memoria, le attività con meno stack, la porta di memoria, il dump del core e le impostazioni che permette di leggere, e puoi scaricarli.",
        "管理者向けです。上部には、トークンでできること・できないことが書かれています。選んだノードの状態・診断パッケージ・ログを読むだけで、操作は一切できず、自動的に失効し、いつでも取り消せます。発行するには、ノードにチェックを入れ、有効期間（既定は2時間）を選び、誰向けかを書きます。Studio はパスワードを再度確認し、トークンを1度だけコピーボタン付きで表示します。再表示はできません。下の一覧には、各トークンのノード、状態、期限、使用回数、最終使用が表示されます。最下部ではノードを選んで診断パッケージまたはログを要求できます。前回の起動の理由、メモリ、スタック残量の少ないタスク、メモリゲート、コアダンプ、読み取りを許可した設定を確認し、ダウンロードもできます。",
        "仅限管理员。顶部说明了令牌能做什么、不能做什么：它只读取你所选节点的健康状态、诊断包和日志，永远不能下达指令，会自动失效，也可随时撤销。签发时，勾选节点、选择有效期（默认 2 小时）并写明给谁用；Studio 会再次要求输入密码，并只显示一次令牌，附带“复制”按钮：之后无法再次查看。下方列表显示每个令牌的节点、状态、到期时间、使用次数和最近一次使用。最下面选择一个节点并请求它的诊断包或日志：你可以查看它上次启动的原因、内存、栈剩余最少的任务、内存闸门、核心转储和允许读取的设置，并可下载。",
        "Para administradores. Em cima, o que um token pode e não pode fazer: só lê a saúde, o pacote de diagnóstico e o registo dos nós que escolher, nunca pode dar uma ordem, caduca sozinho e pode revogá-lo a qualquer momento. Para emitir um, marque os nós, escolha a duração (2 horas por defeito) e escreva para quem é; o Studio pede de novo a palavra-passe e mostra o token uma única vez, com um botão Copiar: não se pode voltar a ver. Em baixo, a lista mostra cada token com os seus nós, o estado, quando caduca, quantas vezes foi usado e quando foi a última. No fim, escolha um nó e peça-lhe o pacote de diagnóstico ou o registo: lê porque arrancou da última vez, a memória, as tarefas com menos pilha, a porta de memória, o despejo de núcleo e as definições que permite ler, e pode descarregá-los."] },
    { target: "tab-installation", placement: "bottom",
      t: ["Installation: export and import", "Instalación: exportar e importar", "Installation: Export und Import", "Installation : exporter et importer", "Installazione: esporta e importa", "インストール：書き出しと取り込み", "安装：导出与导入", "Instalação: exportar e importar"],
      b: ["Keep a copy of the installation, or move it to another machine: the cameras, the designs of the site, the electricity and the network, the rules, the automations, the devices, the solar equipment and the levels of the energy alarms, as one file. The file holds no password, token or key: a camera that is imported needs its user name and password typed in again, and the users are listed only as a reference. Choose which parts to import; importing replaces what is there, so export first if in doubt.",
        "Guarda una copia de la instalación, o llévala a otra máquina: las cámaras, los diseños del sitio, de la electricidad y de la red, las reglas, las automatizaciones, los dispositivos, el equipo solar y los niveles de las alarmas de energía, en un solo archivo. El archivo no lleva ninguna contraseña, token ni clave: una cámara importada necesita que se vuelva a escribir su usuario y contraseña, y los usuarios solo se listan como referencia. Elige qué partes importar; importar sustituye lo que hay, así que exporta antes si dudas.",
        "Bewahren Sie eine Kopie der Installation auf oder nehmen Sie sie auf eine andere Maschine mit: die Kameras, die Entwürfe von Standort, Elektrik und Netz, die Regeln, die Automationen, die Geräte, die Solaranlage und die Stufen der Energiealarme, als eine Datei. Die Datei enthält kein Passwort, keinen Token und keinen Schlüssel: Eine importierte Kamera braucht erneut Benutzer und Passwort, und die Benutzer werden nur als Hinweis gelistet. Wählen Sie, welche Teile importiert werden; Import ersetzt das Vorhandene, exportieren Sie im Zweifel vorher.",
        "Gardez une copie de l'installation, ou emportez-la sur une autre machine : les caméras, les plans du site, de l'électricité et du réseau, les règles, les automatisations, les appareils, l'équipement solaire et les niveaux des alarmes d'énergie, en un seul fichier. Le fichier ne contient aucun mot de passe, jeton ni clé : une caméra importée demande de ressaisir son utilisateur et son mot de passe, et les utilisateurs ne sont listés qu'à titre de référence. Choisissez les parties à importer ; l'import remplace l'existant, exportez donc d'abord dans le doute.",
        "Conserva una copia dell'installazione, o portala su un'altra macchina: le telecamere, i progetti del sito, dell'elettricità e della rete, le regole, le automazioni, i dispositivi, l'impianto solare e i livelli degli allarmi di energia, in un solo file. Il file non contiene alcuna password, token o chiave: una telecamera importata richiede di riscrivere utente e password, e gli utenti sono elencati solo come riferimento. Scegli quali parti importare; importare sostituisce ciò che c'è, quindi esporta prima nel dubbio.",
        "インストール内容のコピーを保管したり、別のマシンへ移したりできます：カメラ、サイト・電気・ネットワークの設計、ルール、オートメーション、デバイス、ソーラー機器、エネルギーアラームの基準を、1つのファイルにまとめます。ファイルにパスワード・トークン・鍵は含まれません。取り込んだカメラはユーザー名とパスワードの再入力が必要で、ユーザーは参考として一覧されるだけです。取り込む部分を選べますが、取り込みは既存を置き換えるので、迷ったら先に書き出しておきましょう。",
        "可把安装内容保存为一份副本，或迁移到另一台机器：摄像头、场地、电气和网络设计、规则、自动化、设备、太阳能设备以及能源报警阈值，全部放在一个文件里。文件不含任何密码、令牌或密钥：导入的摄像头需要重新输入用户名和密码，用户仅作参考列出。可选择要导入的部分；导入会替换现有内容，没把握时请先导出备份。",
        "Guarde uma cópia da instalação, ou leve-a para outra máquina: as câmaras, os desenhos do local, da eletricidade e da rede, as regras, as automatizações, os dispositivos, o equipamento solar e os níveis dos alarmes de energia, num só ficheiro. O ficheiro não leva palavra-passe, token nem chave: uma câmara importada precisa que se escreva de novo o utilizador e a palavra-passe, e os utilizadores só se listam como referência. Escolha que partes importar; importar substitui o que existe, por isso exporte antes se tiver dúvidas."] },
    { target: "tab-console", placement: "bottom",
      t: ["Console: commands as root, with care", "Consola: órdenes como root, con cuidado", "Konsole: Befehle als root, mit Vorsicht", "Console : commandes en root, avec précaution", "Console: comandi come root, con cautela", "コンソール：root権限のコマンド（慎重に）", "控制台：以 root 身份运行命令（请谨慎）", "Consola: comandos como root, com cuidado"],
      b: ["Commands that run as root on this machine, one by one, with a time limit. Use it when something goes wrong and there is no other way in. The console acts as root, so you type your password to open it, and it closes by itself after ten minutes without use. Everything you run is written in the audit trail. Programs that ask questions or need a screen (nano, top) do not work here: use their non-interactive forms. A typo in a command as root can break the system: read before pressing Enter.",
        "Órdenes que se ejecutan como root en esta máquina, una a una, con límite de tiempo. Úsala cuando algo va mal y no hay otra forma de entrar. La consola actúa como root, así que escribes tu contraseña para abrirla, y se cierra sola tras diez minutos sin uso. Todo lo que ejecutes queda en el registro de auditoría. Los programas que hacen preguntas o necesitan pantalla (nano, top) no funcionan aquí: usa sus formas no interactivas. Una errata en una orden como root puede romper el sistema: lee antes de pulsar Intro.",
        "Befehle, die auf dieser Maschine als root laufen, einzeln und mit Zeitlimit. Nutzen Sie sie, wenn etwas schiefgeht und es keinen anderen Zugang gibt. Die Konsole handelt als root; Sie öffnen sie mit Ihrem Passwort, und sie schließt sich nach zehn Minuten ohne Nutzung selbst. Alles, was Sie ausführen, steht im Audit-Protokoll. Programme, die Fragen stellen oder einen Bildschirm brauchen (nano, top), funktionieren hier nicht: Nutzen Sie ihre nicht interaktiven Formen. Ein Tippfehler als root kann das System beschädigen: erst lesen, dann Enter.",
        "Des commandes exécutées en root sur cette machine, une à une, avec une limite de temps. À utiliser quand quelque chose ne va pas et qu'il n'y a pas d'autre accès. La console agit en root : vous saisissez votre mot de passe pour l'ouvrir, et elle se ferme seule après dix minutes sans usage. Tout ce que vous exécutez est écrit dans le journal d'audit. Les programmes qui posent des questions ou ont besoin d'un écran (nano, top) ne fonctionnent pas ici : utilisez leurs formes non interactives. Une faute de frappe en root peut casser le système : lisez avant d'appuyer sur Entrée.",
        "Comandi eseguiti come root su questa macchina, uno a uno, con limite di tempo. Usala quando qualcosa va storto e non c'è altro modo di entrare. La console agisce come root, quindi scrivi la tua password per aprirla, e si chiude da sola dopo dieci minuti senza uso. Tutto ciò che esegui finisce nel registro di audit. I programmi che fanno domande o richiedono uno schermo (nano, top) non funzionano qui: usa le loro forme non interattive. Un errore di battitura come root può rompere il sistema: leggi prima di premere Invio.",
        "このマシンでroot権限のコマンドを1つずつ、時間制限付きで実行します。何か問題が起きて他に入る手段がないときに使います。コンソールはrootとして動くため、開くにはパスワードの入力が必要で、10分間使わないと自動で閉じます。実行した内容はすべて監査記録に残ります。質問をするプログラムや画面が必要なプログラム（nano、top）はここでは動かないので、非対話の形で使ってください。root権限での打ち間違いはシステムを壊し得ます。Enterの前によく読みましょう。",
        "在本机上以 root 身份逐条运行命令，并有时间限制。当出问题且没有其他途径进入时使用。控制台以 root 身份操作，所以打开时要输入你的密码，十分钟不使用会自动关闭。你运行的一切都会记入审计记录。需要提问或占用屏幕的程序（nano、top）在这里无法使用：请改用它们的非交互形式。以 root 身份输错命令可能损坏系统：按 Enter 前务必先读一遍。",
        "Comandos que correm como root nesta máquina, um a um, com limite de tempo. Use-a quando algo corre mal e não há outra forma de entrar. A consola atua como root, por isso escreve a sua palavra-passe para a abrir, e fecha-se sozinha após dez minutos sem uso. Tudo o que executar fica no registo de auditoria. Os programas que fazem perguntas ou precisam de ecrã (nano, top) não funcionam aqui: use as suas formas não interativas. Um erro de escrita como root pode estragar o sistema: leia antes de premir Enter."] },
  ],
};
